def energy_operation_profile(result: Dict[str, object]) -> Dict[str, str]:
    """일간의 힘 배치를 사용자 친화적인 스타일 문장으로 번역한다."""
    raw_label = str(result.get("strength_label", "중화") or "중화")
    strength_idx = result.get("strength_index", "-")
    detail = result.get("strength_detail", {}) or {}
    if not isinstance(detail, dict):
        detail = {}

    peer = float(detail.get("비겁", 0) or 0)
    resource = float(detail.get("인성", 0) or 0)
    output = float(detail.get("식상", 0) or 0)
    wealth = float(detail.get("재성", 0) or 0)
    officer = float(detail.get("관성", 0) or 0)

    refined, refined_desc = refined_strength_interpretation(result)

    if raw_label == "극신강":
        if resource >= max(peer * 1.1, 24):
            name = "지원 증폭형"
            desc = "주변 자원과 배움의 힘까지 받아서 내부 에너지가 크게 불어나는 팔자야. 방향만 잘 잡으면 오래 밀고 갈 수 있어. 근데 과부하랑 고집은 스스로 조절해야 해."
        elif peer >= max(resource * 1.05, 24):
            name = "고압 엔진형"
            desc = "자기 체급이랑 버티는 힘이 아주 강한 팔자야. 추진력은 대단한데, 그 힘을 어디로 배출할지 정하지 않으면 답답함이 쌓일 수 있어."
        else:
            name = "강압 추진형"
            desc = "기본 체급이 아주 강해서 스스로 밀어붙이는 힘이 커. 속도보다 방향 조절이 훨씬 중요해."
    elif raw_label == "신강":
        if "생조형" in refined:
            name = "지원 증폭형"
            desc = "배움, 정보, 보호 자원이 힘을 보태주는 팔자야. 혼자만의 힘보다 좋은 기반을 갖출수록 훨씬 안정적으로 움직일 수 있어."
        elif "자력형" in refined:
            name = "자기 엔진형"
            desc = "내부 체급이랑 버티는 힘으로 먼저 움직이는 팔자야. 독립성이랑 추진력이 장점인데, 유연하게 분산하는 걸 보완해나가면 더 좋아."
        else:
            name = "자력 추진형"
            desc = "스스로 밀고 나가는 힘이 꽤 강한 팔자야. 목표가 분명할수록 성과가 빨리 나와. 너무 과속하는 건 조절하는 게 좋아."
    elif raw_label == "중화":
        if officer >= 25:
            name = "압력 조율형"
            desc = "외부 기준이나 책임, 역할 압력을 느끼며 균형을 잡는 팔자야. 규칙과 자유 사이의 조율이 아주 중요해."
        elif output + wealth >= 42:
            name = "방출 조율형"
            desc = "생각과 행동을 밖으로 풀어 결과를 만드는 팔자야. 무리하게 한꺼번에 쏟아내기보다 리듬을 나눠서 할 때가 훨씬 안정돼."
        else:
            name = "균형 조율형"
            desc = "한쪽으로 과하게 쏠리기보다 상황에 맞춰 밀고 당기는 팔자야. 유연성이랑 판단 균형이 이 사주의 큰 장점이야."
    elif raw_label == "신약":
        if resource + peer >= output + wealth + officer:
            name = "보강 적응형"
            desc = "자기 기반을 보강하면서 움직일 때 가장 안정되는 팔자야. 좋은 환경이랑 루틴을 만들수록 힘이 쭉 살아나거든."
        elif output + wealth >= 38:
            name = "환경 활용형"
            desc = "주변 흐름, 기회, 현실 조건을 읽고 활용하는 팔자야. 혼자 버티기보다 연결이랑 역할 배치가 훨씬 중요해."
        else:
            name = "유연 적응형"
            desc = "강하게 밀어붙이기보다 상황 변화에 맞춰 조절하는 팔자야. 관계랑 환경을 잘 읽을수록 장점이 쭉 살아나."
    else:  # 극신약
        if resource + peer >= 18:
            name = "기반 회복형"
            desc = "먼저 자기 기반이랑 루틴을 회복해야 힘이 살아나는 팔자야. 무리한 확장보다 안전한 구조를 먼저 챙기는 게 중요해."
        else:
            name = "외부 연결형"
            desc = "혼자 밀어붙이기보다 사람, 환경, 제도, 루틴과 연결될 때 힘이 생기는 팔자야. 좋은 판을 잘 고르는 게 제일 중요해."

    raw_hint = f"{raw_label}"
    if strength_idx != "-":
        raw_hint += f" · 지수 {strength_idx}"
    return {
        "name": name,
        "desc": desc,
        "raw": raw_label,
        "hint": raw_hint,
        "refined": refined,
        "refined_desc": refined_desc,
    }


def role_display_name(role: str) -> str:
    """십성 역할을 사용자 화면용 직관 표현으로 바꾼다."""
    mapping = {
        "독립가": "자기 기준형",
        "아이디어 뱅크": "아이디어 설계가",
        "전략가": "현실 전략가",
        "리더": "책임 조율가",
        "책사": "분석 설계가",
        "밸런서": "균형 조율가",
    }
    return mapping.get(str(role or ""), str(role or "균형 조율가"))


def _tone_group_from_adj(adj: str) -> str:
    adj = str(adj or "")
    if "차분" in adj or "냉철" in adj or "서늘" in adj:
        return "cool"
    if "활기" in adj or "뜨겁" in adj or "표현" in adj:
        return "warm"
    if "겉은" in adj or "속은" in adj:
        return "mixed"
    return "mild"


