def compose_character_title(adj: str, noun: str, role: str) -> str:
    """온도감·일간 물상·작동 방식을 사용자에게 바로 와닿는 제목으로 조합한다."""
    tone_group = _tone_group_from_adj(adj)
    role_label = role_display_name(role)
    descriptor = _noun_descriptor(noun, tone_group)

    # 특정 조합은 제목이 길거나 추상적으로 보이지 않게 한 번 더 정리한다.
    special = {
        ("바위", "아이디어 뱅크", "cool"): "차분한 구조형 아이디어 설계가",
        ("바위", "아이디어 뱅크", "mild"): "단단한 기준의 아이디어 설계가",
        ("보석", "아이디어 뱅크", "cool"): "정교하게 다듬는 아이디어 설계가",
        ("대지", "아이디어 뱅크", "cool"): "차분하게 정리하는 아이디어 설계가",
        ("태산", "아이디어 뱅크", "cool"): "든든한 기준의 아이디어 설계가",
        ("맑은 물", "전략가", "cool"): "차분하게 흐름을 읽는 현실 전략가",
        ("바다", "전략가", "cool"): "깊고 차분하게 판을 읽는 현실 전략가",
        ("불꽃", "책사", "cool"): "작지만 선명하게 짚는 분석 설계가",
        ("보석", "책사", "cool"): "정교하고 냉철한 분석 설계가",
    }
    return special.get((noun, role, tone_group), f"{descriptor} {role_label}")


def get_mbti_character(chart: Chart, result: Dict[str, object]) -> Dict[str, str]:
    """1축 조후 + 2축 일간 물상 + 3축 십성 무기를 조합한 캐릭터명."""
    pct = _safe_pct_dict(result)
    day_el = STEMS[chart.day_master]["element"]

    climate = _climate_character_axis(chart, result)
    adj = climate["adj"]
    tone = climate["tone"]
    accent = climate["color"]

    day_master_objects = {
        "甲": "거목", "乙": "화초", "丙": "태양", "丁": "불꽃",
        "戊": "태산", "己": "대지", "庚": "바위", "辛": "보석",
        "壬": "바다", "癸": "맑은 물",
    }
    noun = day_master_objects.get(chart.day_master, "자연")

    output_el = GENERATES[day_el]
    wealth_el = CONTROLS[day_el]
    officer_el = next(e for e in ELEMENTS if CONTROLS[e] == day_el)
    resource_el = next(e for e in ELEMENTS if GENERATES[e] == day_el)
    forces = {
        "독립가": float(pct.get(day_el, 0)),
        "아이디어 뱅크": float(pct.get(output_el, 0)),
        "전략가": float(pct.get(wealth_el, 0)),
        "리더": float(pct.get(officer_el, 0)),
        "책사": float(pct.get(resource_el, 0)),
    }
    role = max(forces, key=forces.get) if forces else "밸런서"
    role_score = forces.get(role, 0.0)
    operation = energy_operation_profile(result)
    operation_display = energy_operation_display_name(operation.get("name", "-"))

    return {
        "title": compose_character_title(adj, noun, role),
        "adj": adj,
        "noun": noun,
        "role": role,
        "role_display": role_display_name(role),
        "tone": tone,
        "color": accent,
        "role_score": f"{role_score:.1f}%",
        "climate_note": climate.get("climate_note", ""),
        "operation": operation_display,
        "operation_raw": operation.get("name", "-"),
        "operation_desc": operation.get("desc", ""),
        "operation_hint": operation.get("hint", ""),
        "operation_refined": operation.get("refined", ""),
    }


def _single_front_snapshot(payload: Dict[str, object]) -> Dict[str, object]:
    """혼자보기 첫 화면과 공유카드에서 함께 쓰는 쉬운 요약 데이터."""
    result = payload.get("result", {}) or {}
    pct = _safe_pct_dict(result)
    dominant, weak = _dominant_and_weak_elements(result)

    order = ["기초체력", "흐름과 연결", "현실작동력"]
    score_map: Dict[str, Dict[str, float]] = {name: {"score": 0.0, "max": 0.0, "pct": 0.0} for name in order}
    display_total = 0.0
    display_max = 0.0
    # v5.150: category_totals_synced_to_total 사용 → 3대 능력치 합계 = 총점 일치
    _cat_rows = (
        category_totals_synced_to_total(result)
        if result.get("categorized_scores") and result.get("total") is not None
        else category_totals(result.get("categorized_scores", {}))
    )
    for row in _cat_rows:
        info = axis_info_from_category(row.get("카테고리", ""))
        primary = info.get("primary", "")
        score = float(row.get("점수", row.get("반영치", 0)) or 0)
        max_score = float(row.get("배점", row.get("기준", 0)) or 0)
        display_total += score
        display_max += max_score
        if primary in score_map:
            pct_score = 0.0 if max_score <= 0 else max(0.0, min(100.0, score / max_score * 100.0))
            score_map[primary] = {"score": score, "max": max_score, "pct": pct_score}

    # 최종 total = result["total"] (base + shinsal + operability 포함)
    display_total = round(float(result.get("total", display_total) or display_total), 1)
    display_max = 100.0 if display_max <= 0 else round(display_max, 1)

    water = float(pct.get("수", 0) or 0)
    fire = float(pct.get("화", 0) or 0)
    temp = max(0.0, min(100.0, 50 + fire * 0.9 - water * 0.9))
    if temp >= 70:
        climate_label = "뜨거운 편"
        climate_note = "열이 강한 쪽으로 기울 수 있어 식히고 정리하는 방향을 함께 봅니다."
        climate_color = "#ef4444"
    elif temp > 50:
        climate_label = "따뜻한 편"
        climate_note = "온기가 살아 있는 편입니다. 과열 여부를 함께 보면 좋습니다."
        climate_color = "#f2c94c"
    else:
        climate_label = "차가운 편"
        climate_note = "차분하고 냉정한 쪽으로 기울 수 있어 온기 보완 여부를 함께 봅니다."
        climate_color = "#3b82f6"

    return {
        "dominant": dominant,
        "weak": weak,
        "elements": pct,
        "scores": score_map,
        "display_total": display_total,
        "display_max": display_max,
        "temp": temp,
        "climate_label": climate_label,
        "climate_note": climate_note,
        "climate_color": climate_color,
    }


# ──────────────────────────────────────────────────────────────
# [사주 맞짱] 코드 생성·검증·파싱 유틸
# ──────────────────────────────────────────────────────────────
_BATTLE_ABC = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"  # 32자 (혼동 글자 제외)


def _b_enc(n: int, length: int) -> str:
    s = []
    for _ in range(length):
        s.append(_BATTLE_ABC[n % 32])
        n //= 32
    return "".join(reversed(s))


def _b_dec(s: str) -> int:
    n = 0
    for c in s.upper():
        if c not in _BATTLE_ABC:
            return -1
        n = n * 32 + _BATTLE_ABC.index(c)
    return n


def encode_battle_code(score: int, today) -> str:
    """score(0-100) + 오늘 날짜 → 6자리 코드 (당일만 유효)."""
    d_fp = (today.year * 10000 + today.month * 100 + today.day) % 32768
    s_enc = _b_enc(min(max(score, 0), 100), 2)
    d_enc = _b_enc(d_fp, 3)
    chk   = _BATTLE_ABC[(score + d_fp) % 32]
    return s_enc + d_enc + chk


def decode_battle_code(code: str, today) -> "int | None":
    """코드 → score. 날짜 불일치·위조 시 None."""
    code = code.strip().upper().replace(" ", "").replace("-", "")
    if len(code) != 6:
        return None
    s    = _b_dec(code[:2])
    d_fp = _b_dec(code[2:5])
    if s < 0 or d_fp < 0:
        return None
    if _BATTLE_ABC[(s + d_fp) % 32] != code[5]:
        return None  # 체크섬 불일치
    if d_fp != (today.year * 10000 + today.month * 100 + today.day) % 32768:
        return None  # 날짜 만료
    return min(100, s)


def calculate_battle_power(payload: dict) -> int:
    """
    맞짱 전투력: 원국 압축(40-70) + 대운(±7) + 세운(±9) + 월운(±12) + 일운(±16)
    → 정규화 raw[-4, 114] → [0, 100]. 매일 변동, 역전 가능 설계.
    원국 점수 차이가 커도 날마다 결과가 달라질 수 있도록 4운 가중치를 높게 설정.
    """
    from datetime import date as _d
    result    = payload.get("result", {}) or {}
    total     = float(result.get("total", 50) or 50)
    chart     = payload.get("chart")
    luck_flow = payload.get("luck_flow") or {}
    useful    = result.get("useful", {}) or {}
    primary   = list(useful.get("primary") or [])
    burden    = list(useful.get("burden")  or [])

    # 원국 점수를 40~70 구간으로 압축 (30pt 범위)
    base = 40.0 + (max(0.0, min(100.0, total)) / 100.0) * 30.0

    def el_dir(el: str) -> float:
        if el in primary: return 1.0
        if el in burden:  return -1.0
        return 0.0

    def gz_factor(gz: str) -> float:
        """천간(0.4) + 지지(0.6) 가중 방향성 반환"""
        if not gz or len(gz) < 2:
            return 0.0
        stem_el   = STEMS.get(gz[0], {}).get("element", "")
        branch_el = BRANCHES.get(gz[1], {}).get("element", "")
        return el_dir(stem_el) * 0.4 + el_dir(branch_el) * 0.6

    # 대운 간지
    dw_gz = str((luck_flow.get("current_daewun") or {}).get("ganzhi", "") or "")

    # 세운 간지 (올해 연도 행 탐색)
    sw_gz = ""
    _yr = str(_d.today().year) + "년"
    for row in (luck_flow.get("sewun_rows") or []):
        if str(row.get("연도", "")) == _yr:
            sw_gz = str(row.get("세운", "") or "")
            break

    # 월운·일운 간지
    month_gz = day_gz = ""
    try:
        if chart:
            _cp = today_compass_payload(chart, result)
            month_gz = str(_cp.get("month_gz", "") or "")
            day_gz   = str(_cp.get("day_gz",   "") or "")
    except Exception:
        pass

    # 각 운별 가중치: 대운 7 / 세운 9 / 월운 12 / 일운 16
    raw = (base
           + gz_factor(dw_gz)    * 7.0
           + gz_factor(sw_gz)    * 9.0
           + gz_factor(month_gz) * 12.0
           + gz_factor(day_gz)   * 16.0)

    # raw 이론 범위 [-4, 114] → [0, 100] 정규화
    score = (raw - (-4.0)) / (114.0 - (-4.0)) * 100.0
    return max(0, min(100, int(round(score))))


def parse_battle_codes_from_text(text: str, today) -> list:
    """단톡방 텍스트에서 '이름: 코드' 쌍을 파싱한다."""
    import re
    results = []
    seen_names = set()
    # 패턴: 이름(한글/영문/숫자 1-10자) + 콜론(또는 공백) + 6자리 코드
    for m in re.finditer(r'([가-힣a-zA-Z0-9_.]{1,10})\s*[:：\s]\s*([A-Z2-9]{6})', text, re.IGNORECASE):
        name = m.group(1).strip()
        code = m.group(2).strip().upper()
        if name in seen_names:
            continue
        seen_names.add(name)
        score = decode_battle_code(code, today)
        results.append({"name": name, "code": code, "score": score, "valid": score is not None})
        if len(results) >= 10:
            break
    return results


