def _reconstruct_payload_from_room_participant(p: Dict) -> Dict:
    """방 참가자 데이터에서 compatibility_analysis용 payload를 재구성한다."""
    pillars = p.get("pillars", {}) or {}

    def _mp(d: "Dict | None") -> Pillar:
        if isinstance(d, dict):
            return Pillar(stem=str(d.get("stem", "甲")), branch=str(d.get("branch", "子")))
        return Pillar("甲", "子")

    hour_d = pillars.get("hour")
    chart = Chart(
        year=_mp(pillars.get("year")),
        month=_mp(pillars.get("month")),
        day=_mp(pillars.get("day")),
        hour=_mp(hour_d) if hour_d else None,
        gender=str(p.get("gender", "남")),
    )

    # adjusted_pct 복원: 신 데이터는 저장값 사용, 구 데이터는 차트에서 계산
    _saved_pct = {k: float(v) for k, v in (p.get("adjusted_pct") or {}).items() if isinstance(v, (int, float))}
    if not _saved_pct or all(v == 0 for v in _saved_pct.values()):
        # 차트 기반 폴백: 천간(1) + 지지(1) + 지장간(0.5)으로 오행 분포 계산
        _counts: Dict[str, float] = {el: 0.0 for el in ELEMENTS}
        _pillar_list = [chart.year, chart.month, chart.day] + ([chart.hour] if chart.hour else [])
        for _pl in _pillar_list:
            _sel = STEMS.get(_pl.stem, {}).get("element", "")
            if _sel in _counts: _counts[_sel] += 1.0
            _bel = BRANCHES.get(_pl.branch, {}).get("element", "")
            if _bel in _counts: _counts[_bel] += 1.0
            for _hs, _ in (BRANCHES.get(_pl.branch, {}).get("hidden", []) or []):
                _hel = STEMS.get(_hs, {}).get("element", "")
                if _hel in _counts: _counts[_hel] += 0.5
        _total_c = sum(_counts.values()) or 1.0
        _saved_pct = {el: round(_counts[el] / _total_c * 100.0, 1) for el in ELEMENTS}

    result = {
        "total":          float(p.get("total", 50) or 50),
        "useful": {
            "primary": list(p.get("useful_primary") or []),
            "burden":  list(p.get("useful_burden")  or []),
        },
        "adjusted_pct":   _saved_pct,
        "strength_label": str(p.get("strength_label", "중화") or "중화"),
    }
    return {"name": str(p.get("name", "")), "chart": chart, "result": result}


def _compute_room_chemistry_matrix(participants: List[Dict]) -> List[List[Dict]]:
    """모든 쌍의 케미를 계산한다. 자기 자신 셀은 None."""
    n = len(participants)
    payloads = [_reconstruct_payload_from_room_participant(p) for p in participants]
    matrix: List[List[Dict]] = []
    for i in range(n):
        row: List[Dict] = []
        for j in range(n):
            if i == j:
                row.append({"score": None, "grade": "-", "summary": "본인"})
            else:
                try:
                    compat = compatibility_analysis(payloads[i], payloads[j])
                    score  = round(float(compat.get("score", 50) or 50))
                    grade, summary = compatibility_grade_summary(score)
                    row.append({"score": score, "grade": grade, "summary": summary})
                except Exception:
                    row.append({"score": 50, "grade": "보통", "summary": "-"})
        matrix.append(row)
    return matrix


def render_chemistry_room_page() -> None:
    """🔮 비밀케미 방 — Supabase 기반 그룹 케미 분석."""

    if _get_supabase() is None:
        st.error("모임 케미 초대는 Supabase 연동이 필요합니다. Streamlit Cloud secrets에 SUPABASE_URL과 SUPABASE_ANON_KEY를 등록해 주세요.")
        if st.button("메인으로", use_container_width=True, key="room_no_sb_home"):
            reset_navigation_to(None)
            st.rerun()
        return

    room_id = st.query_params.get("room", "").strip()

    # ── 방 만들기 뷰 ─────────────────────────────────────────────
    if not room_id:
        _render_create_room_view()
        return

    # ── 방 데이터 로드 ────────────────────────────────────────────
    room = sb_load_room(room_id)
    if room is None:
        st.error("방을 찾을 수 없거나 링크가 만료되었습니다. (케미 방은 24시간 유지)")
        if st.button("새 방 만들기", use_container_width=True, key="room_notfound_new"):
            try:
                st.query_params.clear()
            except Exception:
                pass
            reset_navigation_to("케미방")
            st.rerun()
        return

    participants = list(room.get("participants") or [])
    max_p        = int(room.get("max_participants") or 5)
    status       = str(room.get("status", "waiting"))

    # 전원 입장 → 결과 공개
    if status == "full":
        _render_room_result_view(room_id, participants)
        return

    # 이미 이 방에 참가했는지 (세션 기준)
    joined_name = st.session_state.get(f"_croom_{room_id}_name", "")
    if joined_name:
        _render_room_waiting_view(room_id, participants, max_p, joined_name)
    else:
        _render_room_join_view(room_id, participants, max_p)


def _render_create_room_view() -> None:
    st.markdown("## 🧑‍🤝‍🧑 모임 케미 초대")
    st.caption("최대 5명이 각자 사주를 입력하면 전원 입장 시 자동으로 케미 매트릭스를 공개합니다.")
    st.markdown(
        "<div style='background:#0d0d0d;border-left:4px solid #a855f7;"
        "border-radius:0 10px 10px 0;padding:12px 16px;margin-bottom:14px;"
        "font-size:13px;color:#e8d5a0;line-height:2.2;'>"
        "1️⃣ 방장이 방 만들기 → 링크 생성<br>"
        "2️⃣ 링크를 단톡방에 공유<br>"
        "3️⃣ 참가자가 각자 링크 클릭 → 별명 + 생년월일 입력<br>"
        "4️⃣ 전원 입장 완료되면 자동 공개 🎉"
        "</div>",
        unsafe_allow_html=True,
    )
    max_p = st.radio("최대 인원", [2, 3, 4, 5], index=2, horizontal=True, key="room_max_p")
    if st.button("✨ 방 만들기", type="primary", use_container_width=True, key="room_create_btn"):
        rid = sb_create_room(int(max_p))
        if rid:
            st.session_state["_created_room_id"] = rid
            st.rerun()
        else:
            err = st.session_state.get("_sb_last_error", "unknown")
            st.error(f"방 생성 실패: `{err}`")

    created = st.session_state.get("_created_room_id", "")
    if created:
        room_id_safe = str(created)
        st.success(f"방이 만들어졌습니다! 방 ID: `{room_id_safe}`")
        st.components.v1.html(
            f"""<button onclick="
                var url = window.location.origin + window.location.pathname + '?room={room_id_safe}';
                if(navigator.share){{
                    navigator.share({{title:'모임 케미 초대 참가 링크',url:url}}).catch(function(){{}});
                }} else {{
                    navigator.clipboard.writeText(url).then(function(){{
                        alert('참가 링크가 복사됐어!\\n단톡방에 붙여넣어봐 🔮');
                    }});
                }}
            " style="width:100%;padding:13px;background:#d4a853;color:#0a0a0a;
                border:none;border-radius:10px;font-size:15px;font-weight:800;
                cursor:pointer;">📤 참가 링크 단톡방에 공유</button>""",
            height=60,
        )
        if st.button("🚪 방에 직접 입장하기", use_container_width=True, key="room_self_enter"):
            try:
                st.query_params["room"] = created
            except Exception:
                pass
            st.session_state["_created_room_id"] = ""
            st.rerun()


def _render_room_join_view(room_id: str, participants: List[Dict], max_p: int) -> None:
    st.markdown("## 🧑‍🤝‍🧑 모임 케미 초대 — 참가")
    st.caption(f"방 ID: `{room_id}` · {len(participants)}/{max_p}명 입장 완료")

    if participants:
        joined_html = " &nbsp;·&nbsp; ".join(
            f"<span style='color:#d4a853;'>{html.escape(str(p.get('name','?')))}</span>"
            f"<span style='font-size:11px;color:#888;'> {html.escape(str(p.get('role','?')))}</span>"
            for p in participants
        )
        st.markdown(
            f"<div style='background:#0a0a0a;border:1px solid #3b1f4e;"
            f"border-radius:8px;padding:10px 14px;font-size:13px;margin-bottom:12px;'>"
            f"✅ 입장 완료: {joined_html}</div>",
            unsafe_allow_html=True,
        )

    st.markdown("#### 내 정보 입력")
    st.caption("⚠️ 생년월일은 서버에 저장되지 않습니다. 별명과 사주 팔자(간지)만 저장됩니다.")
    nickname = st.text_input("별명 (10자 이내, 실명 사용 금지)", max_chars=10, key=f"room_nick_{room_id}")

    # 기존 세션 payload 활용 가능 여부
    payload = st.session_state.get("payload")
    has_payload = payload is not None and isinstance(payload, dict) and payload.get("chart") is not None

    if has_payload:
        st.info("내 사주 진단 결과가 있습니다. 별명만 입력하면 바로 참가할 수 있습니다.")
        use_existing = True
    else:
        st.caption("사주 자동 산출: 생년월일과 생시를 입력하면 서버에는 사주 팔자만 저장됩니다.")
        use_existing = False
        birth_str  = st.text_input("생년월일 (YYYY-MM-DD)", key=f"room_birth_{room_id}",
                                   placeholder="예: 1990-03-15")
        btime_str  = st.text_input("태어난 시각 (HH:MM, 모르면 빈칸)", key=f"room_time_{room_id}",
                                   placeholder="예: 14:30")
        gender_sel = st.radio("성별", ["남", "여"], horizontal=True, key=f"room_gender_{room_id}")

    if st.button("🚪 입장하기", type="primary", use_container_width=True, key=f"room_join_{room_id}"):
        name = str(nickname).strip()
        if not name:
            st.error("별명을 입력해 주세요.")
            st.stop()

        if use_existing:
            p_data = _extract_participant_data(payload, name)
        else:
            if Solar is None:
                st.error("자동 산출을 위해 lunar_python이 필요합니다.")
                st.stop()
            try:
                from datetime import date as _d2, time as _t2
                bd = _d2.fromisoformat(birth_str.strip())
                try:
                    bt = _t2.fromisoformat(btime_str.strip()) if btime_str.strip() else _t2(12, 0)
                except Exception:
                    bt = _t2(12, 0)
                _chart, _lf, _res = get_saju_automated(bd, bt, gender_sel)
                tmp_payload = {"chart": _chart, "result": _res, "luck_flow": _lf}
                p_data = _extract_participant_data(tmp_payload, name)
            except Exception as _e:
                st.error(f"사주 산출 오류: {_e}")
                st.stop()

        result_room = sb_join_room(room_id, p_data)
        if result_room is None:
            st.error("입장에 실패했습니다. 방이 가득 찼거나 링크가 만료되었습니다.")
            st.stop()
        st.session_state[f"_croom_{room_id}_name"] = name
        st.rerun()


def _render_room_waiting_view(room_id: str, participants: List[Dict], max_p: int, my_name: str) -> None:
    st.markdown("## 🧑‍🤝‍🧑 모임 케미 초대 — 대기 중")
    remaining = max_p - len(participants)
    st.info(f"✅ **{my_name}** 입장 완료! 아직 **{remaining}명**이 남았습니다. 모두 입장하면 자동으로 공개됩니다.")

    joined_html = ""
    for p in participants:
        joined_html += (
            f"<div style='padding:6px 10px;border-bottom:1px solid #2a1a28;'>"
            f"<span style='color:#d4a853;font-weight:700;'>{html.escape(str(p.get('name','?')))}</span>"
            f"<span style='font-size:11px;color:#888;margin-left:8px;'>{html.escape(str(p.get('role','?')))}</span>"
            f"</div>"
        )
    for _ in range(remaining):
        joined_html += (
            "<div style='padding:6px 10px;border-bottom:1px solid #1a1020;'>"
            "<span style='color:#3a2040;font-style:italic;'>대기 중...</span></div>"
        )
    st.markdown(
        "<div style='background:#0a0a0a;border:1px solid #3b1f4e;"
        "border-radius:10px;overflow:hidden;margin-bottom:14px;'>"
        f"{joined_html}</div>",
        unsafe_allow_html=True,
    )

    if st.button("🔄 새로고침", use_container_width=True, key=f"room_refresh_{room_id}"):
        st.rerun()

    room_id_safe = str(room_id)
    st.components.v1.html(
        f"""<button onclick="
            var base = window.location.origin + window.location.pathname;
            var url = base + '?room={room_id_safe}';
            if(navigator.share){{
                navigator.share({{title:'모임 케미 초대 참가 링크', url:url}}).catch(()=>{{}});
            }} else {{
                navigator.clipboard.writeText(url)
                  .then(()=>alert('참가 링크가 복사됐어!\\n아직 안 들어온 친구한테 보내봐 😊'));
            }}
        " style="width:100%;padding:12px;background:#d4a853;color:#0a0a0a;
            border:none;border-radius:10px;font-size:14px;font-weight:800;
            cursor:pointer;margin-top:4px;">📤 아직 안 온 친구에게 링크 공유</button>""",
        height=56,
    )


def _render_room_result_view(room_id: str, participants: List[Dict]) -> None:
    """전원 입장 완료 — 케미 매트릭스 + 역할 공개."""
    # ── 공개 오버레이 (처음 로드 시 1회) ─────────────────────────
    if not st.session_state.get(f"_croom_{room_id}_revealed"):
        st.components.v1.html("""
<script>
(function(){
    var doc = (window.parent||window).document;
    var ov = doc.createElement('div');
    ov.style.cssText = [
        'position:fixed','top:0','left:0','right:0','bottom:0',
        'background:#080308','z-index:999999',
        'display:flex','flex-direction:column',
        'align-items:center','justify-content:center',
        'transition:opacity 0.7s ease','opacity:1'
    ].join(';');
    ov.innerHTML = [
        '<div style="font-size:3rem;margin-bottom:16px;animation:p 0.9s infinite alternate">🔮</div>',
        '<div style="font-size:1.35rem;color:#d4a853;font-weight:800;margin-bottom:8px;letter-spacing:1px;">케미 공개!</div>',
        '<div style="font-size:0.9rem;color:#b89a6b;">사주 기운을 분석하는 중...</div>',
        '<style>@keyframes p{from{transform:scale(1)}to{transform:scale(1.18)}}</style>'
    ].join('');
    doc.body.appendChild(ov);
    setTimeout(function(){
        ov.style.opacity='0';
        setTimeout(function(){if(ov.parentNode)ov.parentNode.removeChild(ov);},700);
    },1800);
})();
</script>""", height=0)
        st.session_state[f"_croom_{room_id}_revealed"] = True

    n = len(participants)
    names = [str(p.get("name", f"참가자{i+1}")) for i, p in enumerate(participants)]
    matrix = _compute_room_chemistry_matrix(participants)

    st.markdown("## 🧑‍🤝‍🧑 모임 케미 초대 — 케미 공개!")
    st.caption(f"방 ID: `{room_id}` · {n}명 전원 입장 완료")

    # ── 역할 배지 ─────────────────────────────────────────────
    ROLE_COLOR = {"성장형":"#4ade80","표현형":"#fb923c","조율형":"#60a5fa",
                  "결단형":"#f87171","직관형":"#818cf8","균형형":"#b89a6b"}
    ROLE_DESC  = {
        "성장형": "추진력 있게 나아가는 유형",
        "표현형": "분위기를 띄우고 표현이 풍부한 유형",
        "조율형": "갈등을 중재하고 흐름을 맞춰주는 유형",
        "결단형": "빠르게 결정하고 실행하는 유형",
        "직관형": "깊이 읽고 분석하는 유형",
        "균형형": "다양한 역할을 유연하게 맡는 유형",
    }
    badges = ""
    for p in participants:
        role  = str(p.get("role", "균형형"))
        color = ROLE_COLOR.get(role, "#b89a6b")
        badges += (
            f"<div style='display:inline-block;margin:4px;padding:6px 12px;"
            f"background:{color}22;border:1px solid {color}55;border-radius:20px;'>"
            f"<span style='font-weight:800;color:{color};'>{html.escape(str(p.get('name','?')))}</span>"
            f"<span style='font-size:11px;color:#aaa;margin-left:6px;'>{html.escape(role)}</span>"
            f"</div>"
        )
    st.markdown(
        f"<div style='background:#0a0a0a;border:1px solid #3b1f4e;"
        f"border-radius:10px;padding:12px 14px;margin-bottom:14px;'>"
        f"<div style='font-size:12px;color:#b89a6b;font-weight:700;margin-bottom:8px;'>👤 각자의 역할 유형</div>"
        f"{badges}</div>",
        unsafe_allow_html=True,
    )

    # ── 케미 등급 색상 ─────────────────────────────────────────
    GRADE_COLOR = {
        "천생연분 케미":       "#4ade80",
        "쌍방 귀인 케미":      "#34d399",
        "상호보완 케미":       "#60a5fa",
        "친구로 좋은 케미":    "#b89a6b",
        "배려가 필요한 케미":  "#fb923c",
        "안 보면 보고 싶은 케미": "#f87171",
    }

    # ── 모든 쌍 케미 수집 ─────────────────────────────────────
    pairs = []
    best_score, best_pair = -1, ("", "")
    for i in range(n):
        for j in range(i + 1, n):
            cell = matrix[i][j]
            sc   = cell.get("score") or 50
            gd   = cell.get("grade", "친구로 좋은 케미")
            summ = cell.get("summary", "")
            pairs.append((i, j, sc, gd, summ))
            if sc > best_score:
                best_score = sc
                best_pair  = (names[i], names[j])

    # ── 다각형 관계도 SVG ─────────────────────────────────────
    import math as _math
    _W, _H = 340, 340
    _CX, _CY, _R = _W // 2, _H // 2, 120

    # 꼭짓점 좌표 (n=1이면 중앙, n=2면 좌우)
    if n == 1:
        _pts = [(_CX, _CY)]
    elif n == 2:
        _pts = [(_CX - _R, _CY), (_CX + _R, _CY)]
    else:
        _pts = [
            (_CX + _R * _math.cos(_math.radians(-90 + 360 / n * k)),
             _CY + _R * _math.sin(_math.radians(-90 + 360 / n * k)))
            for k in range(n)
        ]

    _svg_lines = []
    for i2, j2, sc, gd, summ in pairs:
        col = GRADE_COLOR.get(gd, "#b89a6b")
        x1, y1 = _pts[i2]; x2, y2 = _pts[j2]
        stroke_w = max(1.5, min(5.0, sc / 20.0))
        opacity  = max(0.35, min(1.0, sc / 100.0))
        _svg_lines.append(
            f"<line x1='{x1:.1f}' y1='{y1:.1f}' x2='{x2:.1f}' y2='{y2:.1f}' "
            f"stroke='{col}' stroke-width='{stroke_w:.1f}' stroke-opacity='{opacity:.2f}' stroke-linecap='round'/>"
        )
        # 선 중점에 등급 텍스트
        mx, my = (x1 + x2) / 2, (y1 + y2) / 2
        _svg_lines.append(
            f"<text x='{mx:.1f}' y='{my:.1f}' text-anchor='middle' dominant-baseline='middle' "
            f"font-size='9' fill='{col}' font-weight='700' "
            f"style='font-family:sans-serif;'>{html.escape(gd)}</text>"
        )

    _svg_nodes = []
    for k, (px, py) in enumerate(_pts):
        _svg_nodes.append(
            f"<circle cx='{px:.1f}' cy='{py:.1f}' r='28' fill='#1a0a28' "
            f"stroke='#a855f7' stroke-width='1.5'/>"
        )
        # 이름 (두 줄로 나누기)
        nm_esc = html.escape(names[k])
        _svg_nodes.append(
            f"<text x='{px:.1f}' y='{py:.1f}' text-anchor='middle' dominant-baseline='middle' "
            f"font-size='11' fill='#fde68a' font-weight='800' "
            f"style='font-family:sans-serif;'>{nm_esc}</text>"
        )

    _svg_inner = "\n".join(_svg_lines + _svg_nodes)
    _svg_html = (
        f"<div style='background:#0a0a0a;border:1px solid #3b1f4e;border-radius:12px;"
        f"padding:14px;margin-bottom:14px;text-align:center;'>"
        f"<div style='font-size:12px;color:#b89a6b;font-weight:700;margin-bottom:8px;'>🔮 케미 관계도</div>"
        f"<svg viewBox='0 0 {_W} {_H}' width='100%' style='max-width:340px;'>{_svg_inner}</svg>"
        f"</div>"
    )
    st.markdown(_svg_html, unsafe_allow_html=True)

    # ── 쌍별 케미 목록 ─────────────────────────────────────────
    _pair_html = ""
    for i2, j2, sc, gd, summ in sorted(pairs, key=lambda x: x[2], reverse=True):
        col = GRADE_COLOR.get(gd, "#b89a6b")
        _pair_html += (
            f"<div style='display:flex;align-items:flex-start;gap:10px;"
            f"padding:8px 12px;border-bottom:1px solid #1a0a28;'>"
            f"<div style='min-width:90px;'>"
            f"<span style='font-size:12px;font-weight:700;color:#d4a853;'>{html.escape(names[i2])}</span>"
            f"<span style='font-size:11px;color:#888;'> &amp; </span>"
            f"<span style='font-size:12px;font-weight:700;color:#d4a853;'>{html.escape(names[j2])}</span>"
            f"</div>"
            f"<div style='flex:1;'>"
            f"<span style='background:{col}22;border:1px solid {col}55;border-radius:12px;"
            f"padding:2px 8px;font-size:11px;font-weight:700;color:{col};'>{html.escape(gd)}</span>"
            f"<div style='font-size:11px;color:#888;margin-top:3px;line-height:1.5;'>{html.escape(summ)}</div>"
            f"</div></div>"
        )
    if _pair_html:
        st.markdown(
            f"<div style='background:#0a0a0a;border:1px solid #3b1f4e;"
            f"border-radius:10px;overflow:hidden;margin-bottom:14px;'>"
            f"<div style='font-size:12px;color:#b89a6b;font-weight:700;padding:10px 14px;border-bottom:1px solid #1a0a28;'>"
            f"🔗 쌍별 케미</div>"
            f"{_pair_html}</div>",
            unsafe_allow_html=True,
        )

    # ── 베스트 케미 ────────────────────────────────────────────
    if best_score >= 0 and best_pair[0]:
        bc      = GRADE_COLOR.get(compatibility_grade_summary(best_score)[0], "#4ade80")
        bc_grade = compatibility_grade_summary(best_score)[0]
        st.markdown(
            f"<div style='background:#0a0a0a;border:2px solid {bc};"
            f"border-radius:12px;padding:14px 18px;text-align:center;margin-bottom:12px;'>"
            f"<div style='font-size:13px;color:{bc};font-weight:700;margin-bottom:6px;'>💫 이 방 최고 케미</div>"
            f"<div style='font-size:1.3rem;color:#fde68a;font-weight:800;'>"
            f"{html.escape(best_pair[0])} &amp; {html.escape(best_pair[1])}</div>"
            f"<div style='font-size:13px;color:{bc};margin-top:4px;'>{html.escape(bc_grade)}</div>"
            f"</div>",
            unsafe_allow_html=True,
        )

    # ── 그룹 전체 케미 진단 ──────────────────────────────────────
    st.markdown("---")
    st.markdown("### 🧩 이 모임 전체 케미 진단")
    st.caption("참가자 전원의 사주를 하나의 집합으로 보고, 모임의 오행 균형·체온·운영 방향을 분석합니다.")
    try:
        _payloads = [_reconstruct_payload_from_room_participant(p) for p in participants]
        _ga = group_chemistry_analysis(_payloads)
        render_group_chemistry_diagnosis(_ga)
    except Exception as _ge:
        st.caption(f"그룹 진단 중 오류가 발생했습니다: {_ge}")

    render_mode_jump_buttons(f"room_result_{room_id}")


# ============================================================
# ⚔️ 사주 맞짱 방 — Supabase 기반 그룹 맞짱
# ============================================================

def render_battle_room_page() -> None:
    """⚔️ 사주 맞짱 방 — Supabase 기반 그룹 배틀."""

    if _get_supabase() is None:
        st.error("맞짱 방은 Supabase 연동이 필요합니다. Streamlit Cloud secrets에 SUPABASE_URL과 SUPABASE_SERVICE_KEY를 등록해 주세요.")
        if st.button("메인으로", use_container_width=True, key="broom_no_sb_home"):
            reset_navigation_to(None)
            st.rerun()
        return

    room_id = st.query_params.get("broom", "").strip()

    if not room_id:
        _render_create_battle_room_view()
        return

    room = sb_load_battle_room(room_id)
    if room is None:
        st.error("방을 찾을 수 없거나 링크가 만료되었습니다. (맞짱 방은 24시간 유지)")
        if st.button("새 방 만들기", use_container_width=True, key="broom_notfound_new"):
            try:
                st.query_params.clear()
            except Exception:
                pass
            reset_navigation_to("맞짱방")
            st.rerun()
        return

    participants = list(room.get("participants") or [])
    max_p        = int(room.get("max_participants") or 5)
    status       = str(room.get("status", "waiting"))

    if status == "full":
        _render_battle_room_result_view(room_id, participants)
        return

    joined_name = st.session_state.get(f"_broom_{room_id}_name", "")
    if joined_name:
        _render_battle_room_waiting_view(room_id, participants, max_p, joined_name)
    else:
        _render_battle_room_join_view(room_id, participants, max_p)


