def _render_battle_room_result_view(room_id: str, participants: List[Dict]) -> None:
    """전원 입장 완료 — 맞짱 랭킹 공개."""
    from datetime import date as _date
    today = _date.today()

    # ── 긴장감 유발 오버레이 (처음 로드 시 1회) ──────────────
    if not st.session_state.get(f"_broom_{room_id}_revealed"):
        st.components.v1.html("""
<script>
(function(){
    var doc = (window.parent||window).document;
    var ov = doc.createElement('div');
    ov.id = 'broom-reveal-overlay';
    ov.style.cssText = [
        'position:fixed','top:0','left:0','right:0','bottom:0',
        'background:#080300',
        'z-index:999999',
        'display:flex','flex-direction:column',
        'align-items:center','justify-content:center',
        'transition:opacity 0.7s ease',
        'opacity:1'
    ].join(';');
    ov.innerHTML = [
        '<div style="font-size:3.2rem;margin-bottom:18px;',
        'animation:pulse 0.8s infinite alternate;">⚔️</div>',
        '<div style="font-size:1.5rem;color:#f59e0b;font-weight:800;',
        'margin-bottom:10px;letter-spacing:1px;">오늘의 승자는...</div>',
        '<div style="font-size:0.95rem;color:#b89a6b;margin-bottom:28px;">',
        '사주 기운을 분석하는 중</div>',
        '<div id="bov-dots" style="font-size:1.6rem;letter-spacing:6px;',
        'color:#f59e0b;width:60px;text-align:center;">●○○</div>',
        '<style>',
        '@keyframes pulse{from{transform:scale(1)}to{transform:scale(1.2)}}',
        '</style>'
    ].join('');
    doc.body.appendChild(ov);
    var frames=['●○○','○●○','○○●','○●○'];
    var fi=0;
    var dotEl=doc.getElementById('bov-dots');
    var iv=setInterval(function(){
        fi=(fi+1)%frames.length;
        if(dotEl) dotEl.textContent=frames[fi];
    },220);
    setTimeout(function(){
        clearInterval(iv);
        ov.style.opacity='0';
        setTimeout(function(){
            if(ov.parentNode) ov.parentNode.removeChild(ov);
        },700);
    },2000);
})();
</script>
""", height=0)
        st.session_state[f"_broom_{room_id}_revealed"] = True

    sorted_p = sorted(participants, key=lambda x: x.get("score", 0), reverse=True)
    winner   = sorted_p[0] if sorted_p else {}
    medal    = ["🥇", "🥈", "🥉"] + ["  "] * 10
    rank_colors = ["#fbbf24", "#94a3b8", "#f97316"] + ["#b89a6b"] * 10

    # 일운 × 원국 : 충·형·십성 기반 직관적 이유 계산
    def _battle_reason(p: Dict) -> str:
        try:
            pillars = p.get("pillars", {}) or {}
            def _mp2(d):
                if isinstance(d, dict):
                    return Pillar(stem=str(d.get("stem","甲")), branch=str(d.get("branch","子")))
                return Pillar("甲","子")
            hour_d = pillars.get("hour")
            _c = Chart(
                year=_mp2(pillars.get("year")), month=_mp2(pillars.get("month")),
                day=_mp2(pillars.get("day")),
                hour=_mp2(hour_d) if hour_d else None,
                gender=str(p.get("gender","남")),
            )
            _tmp_result = {"useful":{"primary":list(p.get("useful_primary") or []),"burden":list(p.get("useful_burden") or [])}}
            _cp = today_compass_payload(_c, _tmp_result)
            day_gz = str(_cp.get("day_gz","") or "")
            if not day_gz or len(day_gz) < 2:
                return "오늘 일운이 사주 기운을 좌우해"

            day_stem   = day_gz[0]
            day_branch = day_gz[1]

            # 원국 모든 지지·천간 수집
            chart_branches = [
                _c.year.branch, _c.month.branch, _c.day.branch
            ] + ([_c.hour.branch] if _c.hour else [])
            chart_stems = [
                _c.year.stem, _c.month.stem, _c.day.stem
            ] + ([_c.hour.stem] if _c.hour else [])
            day_master = str(_c.day_master or _c.day.stem)

            # ① 지지 충(衝) 감지
            clash_map = {frozenset([a, b]): name for a, b, name in CLASHES}
            branch_clashes = []
            for cb in chart_branches:
                key = frozenset([day_branch, cb])
                if key in clash_map:
                    branch_clashes.append((cb, clash_map[key]))
            if branch_clashes:
                cb, cname = branch_clashes[0]
                return f"오늘 일지 {day_branch}이 원국 {cb}랑 충(衝)이야 — 변동 기운이 강해"

            # ② 천간 충(衝) 감지
            stem_clash_map = {frozenset([a, b]): name for a, b, name in STEM_CLASHES}
            for cs in chart_stems:
                key = frozenset([day_stem, cs])
                if key in stem_clash_map:
                    return f"오늘 천간 {day_stem}이 원국 {cs}랑 충이야 — 긴장감 있는 날이야"

            # ③ 형(刑) 감지 — 양방향 체크 (자묘형·삼형 모두 커버)
            penalty_set = {frozenset([a, b]) for a, b, _ in PENALTIES}
            for cb in chart_branches:
                if frozenset([day_branch, cb]) in penalty_set and day_branch != cb:
                    return f"오늘 일지 {day_branch}이 원국 {cb}랑 형(刑)이야 — 마찰 주의"

            # ④ 일간 기준 십성 계산
            tg_stem   = relation_to_day(day_master, day_stem)   if day_stem in STEMS else ""
            tg_branch = relation_to_day(day_master, day_branch) if day_branch in BRANCHES else ""
            # 우선순위: 겁재·편관 등 뾰족한 십성 먼저
            _TG_MSG = {
                "겁재":  f"오늘 겁재 기운이야 — 경쟁심이 올라오고 내 몫 챙기는 날이야",
                "비견":  f"오늘 비견이야 — 내 기준이 또렷해지고 자존감이 강해지는 날이야",
                "상관":  f"오늘 상관이야 — 말이 앞서고 표현이 강해지는 날이야",
                "식신":  f"오늘 식신이야 — 꾸준히 만들고 실행하기 좋은 날이야",
                "편재":  f"오늘 편재야 — 기회 포착과 거래 감각이 살아나는 날이야",
                "정재":  f"오늘 정재야 — 현실 감각과 관리 능력이 또렷해지는 날이야",
                "편관":  f"오늘 편관이야 — 긴장감과 압박이 있지만 돌파력이 생기는 날이야",
                "정관":  f"오늘 정관이야 — 책임감과 신뢰가 빛나는 반듯한 날이야",
                "편인":  f"오늘 편인이야 — 관찰력과 직감이 살아나는 날이야",
                "정인":  f"오늘 정인이야 — 배우고 흡수하고 도움받기 좋은 날이야",
            }
            priority = ["겁재","편관","상관","편재","비견","식신","정재","정관","편인","정인"]
            focus = next((tg for tg in priority if tg in (tg_stem, tg_branch) and tg in _TG_MSG), "")
            if focus:
                return _TG_MSG[focus]

            return f"오늘 일운 {day_gz} — 크게 튀지 않는 평온한 날이야"
        except Exception:
            return "오늘 일운이 사주 기운을 좌우해"

    st.markdown(f"### ⚔️ 오늘의 맞짱 결과 — {today.strftime('%Y년 %m월 %d일')}")
    st.markdown(
        f"<div style='text-align:center;padding:18px 0 10px;'>"
        f"<div style='font-size:2.8rem;'>🏆</div>"
        f"<div style='font-size:1.5rem;font-weight:900;color:#fbbf24;margin-top:4px;'>"
        f"{html.escape(str(winner.get('name','?')))} 승!</div>"
        f"<div style='font-size:13px;color:#b89a6b;margin-top:4px;'>"
        f"{html.escape(_battle_reason(winner))}</div></div>",
        unsafe_allow_html=True,
    )

    rank_html = ""
    for idx, p in enumerate(sorted_p):
        score = p.get("score", 0)
        bar_w = int(score)
        color = rank_colors[idx] if idx < len(rank_colors) else "#b89a6b"
        m     = medal[idx] if idx < len(medal) else " "
        reason = _battle_reason(p)
        rank_html += (
            f"<div style='padding:10px 14px;border-bottom:1px solid #1a1208;'>"
            f"<div style='display:flex;align-items:center;justify-content:space-between;margin-bottom:3px;'>"
            f"<span style='font-size:1.1rem;'>{m} "
            f"<span style='color:{color};font-weight:800;'>{html.escape(str(p.get('name','?')))}</span></span>"
            f"</div>"
            f"<div style='font-size:11px;color:#888;margin-bottom:5px;'>{html.escape(reason)}</div>"
            f"<div style='background:#1a1208;border-radius:4px;height:7px;overflow:hidden;'>"
            f"<div style='width:{bar_w}%;height:100%;background:{color};border-radius:4px;'></div></div>"
            f"</div>"
        )

    st.markdown(
        f"<div style='background:#0a0a0a;border:1px solid #2a2010;"
        f"border-radius:10px;overflow:hidden;margin:12px 0;'>{rank_html}</div>",
        unsafe_allow_html=True,
    )

    # ── 재공유 버튼 ─────────────────────────────────────────
    room_id_safe = str(room_id)
    winner_name_safe = str(winner.get("name", "?")).replace("'", "\\'")
    st.components.v1.html(
        f"""<button onclick="
            var url = window.location.origin + window.location.pathname + '?broom={room_id_safe}';
            var msg = '⚔️ 사주 맞짱 결과\\n🏆 오늘의 승자: {winner_name_safe}\\n' + url;
            if(navigator.share){{
                navigator.share({{title:'사주 맞짱 결과', text:msg, url:url}}).catch(()=>{{}});
            }} else {{
                navigator.clipboard.writeText(url)
                  .then(()=>alert('결과 링크가 복사됐어!\\n단톡방에 공유해봐 ⚔️'));
            }}
        " style="width:100%;padding:13px;background:#f59e0b;color:#1c0a00;
            border:none;border-radius:10px;font-size:15px;font-weight:800;
            cursor:pointer;margin-top:4px;">📤 결과 단톡방에 공유</button>""",
        height=60,
    )

    render_mode_jump_buttons(f"broom_result_{room_id}")


def render_battle_ranking_page() -> None:
    """⚔️ 사주 맞짱 — 코드 붙여넣기 → 결과 링크 생성 → 단톡 공유."""
    import json as _json
    import urllib.parse as _up
    from datetime import date as _date
    today = _date.today()

    st.markdown("## ⚔️ 사주 맞짱")

    # ── 사용법 안내 ──────────────────────────────────────────
    st.markdown(
        "<div style='background:#0d0d0d;border-left:4px solid #f59e0b;"
        "border-radius:0 10px 10px 0;padding:12px 16px;margin-bottom:14px;"
        "font-size:13px;color:#e8d5a0;line-height:2.2;'>"
        "1️⃣ 각자 내 사주 진단 후 <b>오늘의 맞짱 코드</b>를 단톡에 공유<br>"
        "2️⃣ 단톡 내용을 아래에 <b>붙여넣기</b><br>"
        "3️⃣ <b>결과 링크 생성</b> 버튼 → 링크를 단톡에 공유<br>"
        "4️⃣ 모두가 링크 클릭 → 동시에 순위 확인 🎉"
        "</div>",
        unsafe_allow_html=True,
    )

    # ── 붙여넣기 영역 ────────────────────────────────────────
    raw_text = st.text_area(
        "단톡방 내용 붙여넣기 (최대 10명)",
        placeholder="홍길동: K7X2MQ\n김철수: P3RT9W\n이영희: X8KL4N",
        height=160,
        key="battle_paste_area",
        help="'이름: 코드' 형식이면 자동 인식해. 단톡 내용을 그대로 복사해서 붙여넣어도 돼.",
    )

    # ── 실시간 파싱 결과 표시 ────────────────────────────────
    entries = []
    if raw_text.strip():
        entries = parse_battle_codes_from_text(raw_text, today)
        valid_e   = [e for e in entries if e["valid"]]
        invalid_e = [e for e in entries if not e["valid"]]
        if valid_e:
            names_str = " · ".join(e["name"] for e in valid_e)
            st.success(f"✅ {len(valid_e)}명 인식됨: {names_str}")
        if invalid_e:
            st.caption(f"⚠️ 만료된 코드 (오늘 생성 코드 아님): "
                       f"{', '.join(e['name'] for e in invalid_e)}")
        if not valid_e and entries:
            st.error("인식된 코드가 모두 만료됐어. 오늘 생성된 코드인지 확인해봐.")

    # ── 결과 링크 생성 버튼 ──────────────────────────────────
    valid_e = [e for e in entries if e.get("valid")]
    if valid_e:
        if st.button("🔗 결과 링크 생성", type="primary",
                     use_container_width=True, key="battle_genlink_btn"):
            param   = ",".join(f"{e['name']}:{e['code']}" for e in valid_e)
            encoded = _up.quote(param, safe=":,")
            st.session_state["battle_link_encoded"] = encoded
            st.session_state["battle_link_entries"] = valid_e

    # ── 생성된 링크 공유 영역 ────────────────────────────────
    if st.session_state.get("battle_link_encoded"):
        encoded  = st.session_state["battle_link_encoded"]
        link_e   = st.session_state.get("battle_link_entries", [])
        sorted_e = sorted(link_e, key=lambda x: x["score"], reverse=True)
        medal    = ["🥇", "🥈", "🥉"] + [" "] * 7

        # 미리보기 (점수 미표시)
        preview = " · ".join(
            f"{medal[i].strip() or str(i+1)+'위'} {e['name']}"
            for i, e in enumerate(sorted_e)
        )
        st.markdown(
            f"<div style='background:#0d0d0d;border:1px solid #2a2010;"
            f"border-radius:10px;padding:10px 14px;font-size:13px;"
            f"color:#e8d5a0;line-height:1.9;'>"
            f"<b>📋 결과 미리보기</b><br>{preview}</div>",
            unsafe_allow_html=True,
        )

        # Supabase 사용 가능하면 짧은 URL (?battle=ID), 없으면 기존 ?b= 방식
        if _get_supabase() is not None:
            battle_participants = [{"name": e["name"], "score": e["score"]} for e in valid_e]
            bid = sb_save_battle(battle_participants)
        else:
            bid = None

        encoded_safe = str(encoded)
        bid_safe     = str(bid) if bid else ""
        st.components.v1.html(
            f"""<button onclick="
                var base = window.location.origin + window.location.pathname;
                var bid  = '{bid_safe}';
                var url  = bid ? (base + '?battle=' + bid) : (base + '?b=' + '{encoded_safe}');
                if(navigator.share){{
                    navigator.share({{title:'사주 맞짱 결과', url:url}}).catch(()=>{{}});
                }} else {{
                    navigator.clipboard.writeText(url)
                      .then(()=>alert('결과 링크가 복사됐어!\\n단톡방에 붙여넣어봐.'));
                }}
            " style="width:100%;padding:13px;background:#f59e0b;color:#1c0a00;
                border:none;border-radius:10px;font-size:15px;font-weight:800;
                cursor:pointer;margin-top:6px;">📤 결과 링크 단톡방에 공유</button>""",
            height=60,
        )

    # ── 내 코드 확인 버튼 ────────────────────────────────────
    st.divider()
    st.caption("아직 내 코드가 없으면 먼저 내 사주를 분석해봐.")
    if st.button("🌸 내 사주 진단하러 가기", use_container_width=True, key="battle_goto_single"):
        reset_navigation_to("혼자 보기")
        st.rerun()


def _render_battle_result_from_url(b_param: str) -> None:
    """URL ?b= 파라미터로부터 맞짱 결과 화면을 표시한다.
    누가 링크를 열어도 동일한 순위가 나온다."""
    import json as _json
    from datetime import date as _d
    today = _d.today()

    # ── 긴장감 유발 로딩 오버레이 (1.8초) ────────────────────
    st.components.v1.html("""
<script>
(function() {
    var doc = (window.parent || window).document;
    var ov = doc.createElement('div');
    ov.id = 'battle-reveal-overlay';
    ov.style.cssText = [
        'position:fixed','top:0','left:0','right:0','bottom:0',
        'background:#080308',
        'z-index:999999',
        'display:flex','flex-direction:column',
        'align-items:center','justify-content:center',
        'transition:opacity 0.7s ease',
        'opacity:1'
    ].join(';');
    ov.innerHTML = [
        '<div style="font-size:3.2rem;margin-bottom:18px;',
        'animation:pulse 0.9s infinite alternate;">⚔️</div>',
        '<div style="font-size:1.45rem;color:#f59e0b;font-weight:800;',
        'margin-bottom:10px;letter-spacing:1px;">오늘의 승자는...</div>',
        '<div style="font-size:0.95rem;color:#b89a6b;margin-bottom:28px;">',
        '사주 기운을 분석하는 중</div>',
        '<div id="ov-dots" style="font-size:1.6rem;letter-spacing:6px;',
        'color:#f59e0b;width:60px;text-align:center;">●○○</div>',
        '<style>',
        '@keyframes pulse{from{transform:scale(1)}to{transform:scale(1.18)}}',
        '</style>'
    ].join('');
    doc.body.appendChild(ov);

    var frames = ['●○○','○●○','○○●','○●○'];
    var fi = 0;
    var dotEl = doc.getElementById('ov-dots');
    var iv = setInterval(function(){
        fi = (fi + 1) % frames.length;
        if(dotEl) dotEl.textContent = frames[fi];
    }, 220);

    setTimeout(function(){
        clearInterval(iv);
        ov.style.opacity = '0';
        setTimeout(function(){
            if(ov.parentNode) ov.parentNode.removeChild(ov);
        }, 700);
    }, 1800);
})();
</script>
""", height=0)

    # ── 파싱: "홍길동:K7X2MQ,김철수:B3NRPX,..." ──────────────
    entries = []
    for part in b_param.split(","):
        part = part.strip()
        if ":" not in part:
            continue
        name, _, code = part.partition(":")
        name = name.strip()
        code = code.strip().upper()
        if not name or len(code) != 6:
            continue
        score = decode_battle_code(code, today)
        entries.append({"name": name, "code": code,
                        "score": score, "valid": score is not None})

    valid   = sorted([e for e in entries if e["valid"]],
                     key=lambda x: x["score"], reverse=True)
    invalid = [e for e in entries if not e["valid"]]

    st.markdown(f"### ⚔️ 오늘의 맞짱 결과 — {today.strftime('%Y년 %m월 %d일')}")

    if not valid:
        st.error("유효한 코드가 없거나 만료된 결과야. 오늘 생성된 코드로 다시 시도해봐.")
        if invalid:
            st.caption(f"인식된 참가자: {', '.join(e['name'] for e in invalid)}")
        if st.button("⚔️ 맞짱 다시 시작", use_container_width=True, key="battle_restart_err"):
            try:
                st.query_params.clear()
            except Exception:
                pass
            st.rerun()
        return

    # ── 랭킹 카드 ────────────────────────────────────────────
    medal       = ["🥇", "🥈", "🥉"] + ["  "] * 7
    RANK_COLORS = ["#fbbf24", "#94a3b8", "#f97316"] + ["#b89a6b"] * 7
    _rank_html  = ""
    for idx, e in enumerate(valid):
        score = e["score"]
        bar_w = int(score)
        col   = RANK_COLORS[idx] if idx < len(RANK_COLORS) else "#b89a6b"
        _rank_html += (
            f"<div style='margin-bottom:10px;'>"
            f"<div style='display:flex;justify-content:space-between;align-items:center;"
            f"font-size:13px;color:#e8d5a0;margin-bottom:2px;'>"
            f"<span style='font-weight:700;font-size:15px;'>"
            f"{medal[idx]} {idx+1}위 &nbsp; {e['name']}</span>"
            f"</div>"
            f"<div style='font-size:11px;color:#888;margin-bottom:5px;'>오늘 일운·월운 기운이 좌우해</div>"
            f"<div style='background:#0f0f0f;border-radius:999px;"
            f"overflow:hidden;height:10px;'>"
            f"<div style='width:{bar_w}%;height:100%;background:{col};"
            f"border-radius:999px;'></div>"
            f"</div>"
            f"</div>"
        )

    winner = valid[0]
    st.markdown(
        f"<div style='background:#141414;border:2px solid #f59e0b;"
        f"border-radius:14px;padding:16px 18px;margin-bottom:12px;'>"
        f"<div style='font-size:13px;color:#f59e0b;font-weight:700;"
        f"letter-spacing:1px;margin-bottom:12px;'>"
        f"⚔️ 사주 맞짱 랭킹 — {today.strftime('%Y.%m.%d')}</div>"
        f"{_rank_html}"
        f"<div style='margin-top:14px;text-align:center;font-size:16px;"
        f"color:#fbbf24;font-weight:800;'>👑 오늘의 승자: {winner['name']}</div>"
        f"</div>",
        unsafe_allow_html=True,
    )

    if invalid:
        st.caption(f"⚠️ 오늘 코드 아님 또는 오류: {', '.join(e['name'] for e in invalid)}")

    # ── 랭킹 기준 안내 ───────────────────────────────────────
    st.markdown(
        "<div style='background:#0f0f0f;border-radius:10px;padding:10px 14px;"
        "font-size:12px;color:#8a7060;line-height:1.9;margin-bottom:10px;'>"
        "📌 <b>랭킹 기준</b><br>"
        "오늘의 순위는 타고난 원국(사주팔자)보다 <b>일운 · 월운 · 세운 · 대운</b>에 "
        "더 높은 가중치를 두어 결정됩니다. 원국이 강해도 오늘 운이 나쁘면 질 수 있고, "
        "원국이 약해도 오늘 운이 좋으면 이길 수 있어요. 순위는 매일 달라집니다."
        "</div>",
        unsafe_allow_html=True,
    )

    # ── 결과 재공유 버튼 (현재 URL 그대로 공유) ──────────────
    share_lines = [f"⚔️ 사주 맞짱 결과 ({today.strftime('%Y.%m.%d')})"]
    for idx, e in enumerate(valid):
        share_lines.append(f"{medal[idx].strip() or str(idx+1)+'위'} {e['name']}")
    share_lines.append(f"👑 오늘의 승자: {winner['name']}")
    share_text_safe = "\\n".join(share_lines).replace("'", "\\'")

    st.components.v1.html(
        f"""<button onclick="
            var url = window.location.href;
            var txt = '{share_text_safe}';
            if(navigator.share){{
                navigator.share({{title:'사주 맞짱 결과', text:txt, url:url}}).catch(()=>{{}});
            }} else {{
                navigator.clipboard.writeText(url)
                  .then(()=>alert('결과 링크가 복사됐어!\\n단톡방에 붙여넣어봐.'));
            }}
        " style="width:100%;padding:12px;background:#f59e0b;color:#1c0a00;
            border:none;border-radius:10px;font-size:15px;font-weight:800;
            cursor:pointer;">📤 이 결과 단톡방에 공유</button>""",
        height=56,
    )

    st.divider()
    st.caption("나도 맞짱에 도전하고 싶다면?")
    if st.button("⚔️ 내 사주로 맞짱 참가", use_container_width=True, key="battle_join_from_result"):
        try:
            st.query_params.clear()
        except Exception:
            pass
        reset_navigation_to("맞짱방")
        st.rerun()




def _axis_bias_summary(score_map: Dict[str, Dict[str, float]]) -> Dict[str, str]:
    order = ["기초체력", "흐름과 연결", "현실작동력"]
    label_short = {
        "기초체력": "기초체력",
        "흐름과 연결": "흐름",
        "현실작동력": "작동력",
    }
    pcts = {name: float((score_map.get(name, {}) or {}).get("pct", 0.0) or 0.0) for name in order}
    top = max(order, key=lambda n: pcts[n])
    low = min(order, key=lambda n: pcts[n])
    spread = pcts[top] - pcts[low]

    if spread < 6:
        headline = "세 축이 비교적 고르게 분포"
        subline = "한쪽으로 크게 치우치기보다 전반적으로 균형에 가깝습니다."
    else:
        headline = f"{label_short[top]} 쪽이 더 두드러짐"
        subline = f"{label_short[top]} 축이 상대적으로 강하고, {label_short[low]} 축은 상대적으로 약한 편입니다."

    return {
        "headline": headline,
        "subline": subline,
        "top": label_short[top],
        "low": label_short[low],
    }


def _triangle_axis_svg(score_map: Dict[str, Dict[str, float]]) -> str:
    """차이를 더 극적으로 보여주는 3축 삼각 그래프."""
    import math as _math

    order = ["기초체력", "흐름과 연결", "현실작동력"]
    labels = {
        "기초체력": "기초체력",
        "흐름과 연결": "흐름",
        "현실작동력": "작동력",
    }
    raw = [float((score_map.get(name, {}) or {}).get("pct", 0.0) or 0.0) for name in order]
    lo, hi = min(raw), max(raw)
    span = max(hi - lo, 1e-6)

    def dramatic_pct(v: float) -> float:
        rel = (v - lo) / span if span > 0 else 0.5
        rel_scaled = 32.0 + rel * 58.0
        abs_scaled = 26.0 + v * 0.62
        return max(22.0, min(94.0, rel_scaled * 0.68 + abs_scaled * 0.32))

    display = [dramatic_pct(v) for v in raw]

    cx, cy, r = 160, 156, 104
    angles = [(-90 + i * 120) * _math.pi / 180 for i in range(3)]

    grid = []
    for idx, ratio in enumerate((0.22, 0.44, 0.66, 0.88, 1.0), start=1):
        pts = [f"{cx + _math.cos(a) * r * ratio:.1f},{cy + _math.sin(a) * r * ratio:.1f}" for a in angles]
        opacity = 0.08 if idx < 5 else 0.20
        width = 1.0 if idx < 5 else 1.6
        grid.append(f"<polygon points='{' '.join(pts)}' fill='none' stroke='rgba(212,168,83,{opacity})' stroke-width='{width}'/>")

    axes = []
    labels_svg = []
    points = []
    for name, ang, disp_v, raw_v in zip(order, angles, display, raw):
        px = cx + _math.cos(ang) * r * (disp_v / 100.0)
        py = cy + _math.sin(ang) * r * (disp_v / 100.0)
        points.append(f"{px:.1f},{py:.1f}")
        ax = cx + _math.cos(ang) * r
        ay = cy + _math.sin(ang) * r
        axes.append(f"<line x1='{cx}' y1='{cy}' x2='{ax:.1f}' y2='{ay:.1f}' stroke='rgba(110,82,98,.18)' stroke-width='1.2'/>")

        lx = cx + _math.cos(ang) * (r + 34)
        ly = cy + _math.sin(ang) * (r + 30)
        anchor = "middle"
        if lx < cx - 12:
            anchor = "end"
        elif lx > cx + 12:
            anchor = "start"

        labels_svg.append(
            f"<text x='{lx:.1f}' y='{ly:.1f}' text-anchor='{anchor}' dominant-baseline='middle' font-size='14' font-weight='900' fill='#4f3742'>{html.escape(labels[name])}</text>"
        )
        labels_svg.append(
            f"<text x='{lx:.1f}' y='{ly + 18:.1f}' text-anchor='{anchor}' dominant-baseline='middle' font-size='12' font-weight='900' fill='#92400e'>{raw_v:.0f}</text>"
        )

    poly_shadow = f"<polygon points='{' '.join(points)}' fill='rgba(212,168,83,.10)' stroke='none' transform='translate(0,2)'/>"
    poly = f"<polygon points='{' '.join(points)}' fill='rgba(212,168,83,.22)' stroke='#92400e' stroke-width='4.0'/>"
    dots = "".join([f"<circle cx='{p.split(',')[0]}' cy='{p.split(',')[1]}' r='6' fill='#92400e' stroke='#fff' stroke-width='1.8'/>" for p in points])
    center_glow = f"<circle cx='{cx}' cy='{cy}' r='16' fill='rgba(212,168,83,.07)'/>"

    return (
        "<div style='background:rgba(255,255,255,.96);border:1px solid rgba(212,168,83,.30);border-radius:18px;"
        "padding:.30rem .24rem .14rem;box-sizing:border-box;aspect-ratio:1/1;display:flex;align-items:center;justify-content:center;'>"
        "<svg viewBox='0 0 320 330' width='100%' height='100%' role='img' style='display:block;margin:auto;'>"
        + center_glow + "".join(grid + axes) + poly_shadow + poly + dots + "".join(labels_svg) +
        "</svg></div>"
    )


