def _today_luck_background_line(payload: Dict[str, object]) -> str:
    """오늘 카드 상단에서 대운·세운 배경을 짧게 보여준다."""
    luck_flow = payload.get("luck_flow") or {}
    if not isinstance(luck_flow, dict) or not luck_flow:
        return "대운·세운은 자동 산출 정보가 있을 때 함께 참고합니다."
    parts: List[str] = []
    current = luck_flow.get("current_daewun") or {}
    if isinstance(current, dict) and current.get("ganzhi"):
        parts.append(f"대운 {current.get('ganzhi')} · {current.get('start_age', '-')}세부터")
    rows = luck_flow.get("sewun_rows") or []
    this_year = f"{date.today().year}년"
    if isinstance(rows, list):
        for row in rows:
            if isinstance(row, dict) and str(row.get("연도", "")) == this_year:
                parts.append(f"세운 {row.get('세운', '-')}")
                break
    return " / ".join(parts) if parts else "대운·세운은 큰 배경, 일운은 오늘의 체감 바람으로 봅니다."


def render_today_quick_entry(payload: Dict[str, object]) -> None:
    """오늘의 처방 첫 화면: 핵심 4개만 Streamlit 기본 컴포넌트로 표시한다."""
    chart = payload.get("chart")
    result = payload.get("result", {}) or {}
    if chart is None:
        return

    compass = today_compass_payload(chart, result)
    bg_line = _today_luck_background_line(payload)

    ten_god_title = "십성 흐름"
    ten_god_body = str(compass.get("day_tengod_summary") or compass.get("ten_god_focus") or "십성 정보 제한")
    prescription = str(compass.get("ten_god_action") or compass.get("prescription") or compass.get("ten_god_short") or "-")
    interaction_overview = str(compass.get("interaction_overview") or "특이 신호 없음")

    st.markdown("### 🌤 오늘의 처방")
    st.caption(f"{compass.get('date', '-')} · 오늘의 기운 {compass.get('day_gz', '-')}")

    # ── 진단 풀이 텍스트 ─────────────────────────────────
    _day_gz   = str(compass.get("day_gz", "-"))
    _day_title = str(compass.get("day_luck_title", _day_gz))
    _inter    = str(compass.get("interaction_overview") or "")
    _ten_god  = str(compass.get("day_tengod_summary") or "")
    _presc    = str(compass.get("ten_god_action") or compass.get("prescription") or "")

    # 십성 → 오늘 성격 한 줄
    _tengod_story = {
        "비견": "오늘 비견 기운이야. 나랑 비슷한 처지, 비슷한 힘을 가진 사람이 옆에 있거든 — 경쟁이 될 수도 있고 든든한 동료가 될 수도 있어. 이 사람아, 오늘은 이기느냐 지느냐보다 같이 가느냐를 먼저 생각해봐. 혼자 다 하려고 힘 빼지 마 — 손 잡을 사람 하나 찾아봐. 그 쪽이 훨씬 빨리 간다고, 내가 보장해.",
        "겁재": "오늘은 겁재 기운이야, 이 녀석. 조심해. 경쟁 신호, 분쟁 신호가 슬쩍 올라와 있거든. 내 걸 지키려다 오히려 더 잃는 날이야 — 억지로 붙잡지 마. 돈 문제, 다툼 문제 생길 것 같으면 오늘만큼은 딱 한 발 빼. 양보가 지는 게 아니야 — 오늘은 그게 제일 현명한 거거든. 알겠어?",
        "식신": "오늘은 식신 기운이야 — 몸이 원하는 대로 하면 돼. 먹고 싶은 거 먹고, 하고 싶은 거 하고, 만들고 싶은 거 만들어봐. 이 기운은 긴장하면 죽어버리거든. 억지로 생산적일 필요 없어. 거봐, 오늘 쉬는 게 내일의 힘이야 — 느긋하게 보내는 날이 충전하는 날이야. 쉬는 것도 실력이야.",
        "상관": "아이고, 오늘 상관 기운이네. 말이 청산유수처럼 나오고, 아이디어가 팡팡 터지는 날이거든. 창의적인 일, 표현하는 일, 설득하는 일에 딱 맞아. 근데 있잖아 — 이 기운이 강하면 말실수도 같이 와. 하고 싶은 말 다 뱉기 전에 한 박자만 쉬어봐. 특히 윗사람 앞에서는 더 조심해, 알겠지? 머리는 활짝 열고, 입은 살짝 조여놔.",
        "편재": "오늘은 편재 기운이야. 돈이 움직이고 사람이 움직이는 날이거든. 기회가 반짝 눈앞에 나타날 수 있어 — 보이면 잡아봐. 근데 이 녀석, 이 기운은 너무 욕심 부리면 손가락 사이로 모래처럼 빠져나가거든. 쯧쯧. 적당히 잡고 적당히 놔주는 게 오늘의 기술이야. 흘러가는 건 보내줘.",
        "정재": "오늘은 정재 기운 — 꼼꼼하고 안정적인 날이야. 계획해둔 거 차근차근 실행하기에 딱 좋거든. 서두르거나 즉흥적으로 움직이면 오히려 어긋나 — 이 사람아, 오늘만큼은 서두르지 마. 정해진 대로, 원칙대로 가면 돼. 급하게 굴지 않아도 충분히 잘 된다고, 내가 장담해.",
        "편관": "오늘은 편관 기운이야. 긴장감이 공중에 떠 있는 날이거든. 결단을 요구받거나 압박을 받을 수 있어. 이럴 때 질질 끌면 더 힘들어지거든 — 야, 딱 끊어서 결정해. 두려움은 일단 옆에 내려놓고 지금 할 수 있는 것 먼저 해. 편관은 도망갈수록 커지고, 맞부딪히면 오히려 작아지는 기운이야. 도망가지 마.",
        "정관": "오늘은 정관 기운 — 반듯하게 가는 날이야. 바르게 행동하고, 약속 지키고, 책임 다하면 나중에 인정받아. 눈앞의 이익보다 의리랑 원칙이 더 중요한 날이거든. 이 사람아, 오늘 잘 쌓아둔 신뢰가 나중에 든든한 자산이 돼 — 지금 하는 행동 하나하나가 평판을 만든다는 거, 잊지 마.",
        "편인": "오늘은 편인 기운이야. 직관이 살아나고, 영감이 번뜩이는 날이거든. 논리보다 느낌이 더 잘 맞는 날이야. 혼자 공부하거나, 조용히 생각 정리하거나, 새로운 분야 탐색하기에 딱 좋아. 대신 있잖아 — 오늘은 시끄러운 자리에 있으면 기운이 산만해지거든. 나만의 시간 좀 확보해봐. 이거 중요해.",
        "정인": "오늘은 정인 기운 — 배우고 받아들이는 날이야. 누가 조언해주면 귀담아 들어봐, 이 사람아. 스승이 따로 없어도 오늘 만나는 사람, 읽는 글, 보는 것 하나하나가 다 가르침이 될 수 있거든. 내가 모른다는 걸 인정하는 게 오늘의 힘이야. 거봐, 받아들이는 자세가 열려 있을수록 오늘 더 많은 게 채워지거든.",
    }
    _tg_key = ""
    for _tg in _tengod_story:
        if _tg in _ten_god:
            _tg_key = _tg
            break
    _tg_line = _tengod_story.get(_tg_key, f"오늘 기운은 「{_day_gz}」이야. 하루를 천천히 살피며 가봐.")

    # 신호 여부 — 의사 처방 말투 (형 > 충 > 합 순 우선)
    _signal_line = ""
    if "형" in _inter:
        _signal_line = " 오늘은 형살 신호가 잡혀, 이 사람아. 억누르거나 억눌리는 기운이 껴 있는 날이거든. 속에서 뭔가 꽉 막히는 느낌 들 수 있어 — 그거 그냥 놔두면 안 돼. 감정을 안으로만 삭이지 말고, 가까운 사람한테라도 살짝 털어내봐. 말 못 할 상황이면 몸을 움직여 — 산책, 운동, 청소 뭐든. 그게 약이야."
    elif "충" in _inter:
        _signal_line = " 오늘은 충 신호야. 내 원국이랑 오늘 기운이 서로 부딪히는 날이거든. 막히거나 어긋나는 일 생겨도 놀라지 마 — 오늘 원래 그런 날이야. 억지로 밀어붙이면 더 크게 부딪혀, 거봐. 오늘만큼은 유연하게 돌아가는 길을 찾아봐. 고집 부릴수록 손해야, 알겠지?"
    elif "합" in _inter:
        _signal_line = " 오늘은 합 신호야 — 이거 좋은 거야. 내 원국이랑 오늘 기운이 잘 엮이는 날이거든. 사람이 먼저 다가오거나, 생각지 못한 연결이 생길 수 있어. 억지로 만들려 하지 않아도 자연스럽게 맞아 들어가는 흐름이니까 — 열린 마음으로 받아들여봐. 이런 날 놓치면 아깝거든."

    # 처방 한 줄
    _rx_line = f" {_presc}" if _presc and _presc not in ("-", "없음") else ""

    # 오늘 흐름 지수 — 충·형·겁재(주의) / 합(좋음) / 기타(보통)
    _is_warn = "충" in _inter or "형" in _inter or "겁재" in _ten_god
    _is_good = "합" in _inter and not _is_warn
    if _is_warn:
        _flow_grade, _flow_color = "⚠️ 주의", "#dc2626"
    elif _is_good:
        _flow_grade, _flow_color = "✅ 좋음", "#16a34a"
    else:
        _flow_grade, _flow_color = "🔵 보통", "#2563eb"

    _story_text = f"{_tg_line}{_signal_line}{_rx_line}"

    st.markdown(
        f"<div style='background:#0d1e14;border-left:4px solid #4ade80;padding:12px 16px;"
        f"border-radius:8px;margin-bottom:12px;font-size:14px;color:#14532d;line-height:1.8;'>"
        f"<div style='display:flex;justify-content:space-between;align-items:center;"
        f"margin-bottom:5px;'>"
        f"<span style='font-size:12px;color:#a0b4bc;'>오늘 처방전 · {_day_gz}</span>"
        f"<span style='font-size:12px;font-weight:700;color:{_flow_color};'>"
        f"오늘 흐름 {_flow_grade}</span>"
        f"</div>"
        f"{_story_text}</div>",
        unsafe_allow_html=True,
    )

    try:
        shell = st.container(border=True)
    except TypeError:
        shell = st.container()

    with shell:
        top_left, top_right = st.columns(2)
        with top_left:
            try:
                card = st.container(border=True)
            except TypeError:
                card = st.container()
            with card:
                st.markdown("**오늘 들어온 일운 / 큰 배경**")
                st.markdown(str(compass.get("day_luck_title", compass.get("day_gz", "-"))))
                st.caption(str(bg_line))

        with top_right:
            try:
                card = st.container(border=True)
            except TypeError:
                card = st.container()
            with card:
                st.markdown(f"**{ten_god_title}**")
                st.markdown(ten_god_body)

        bottom_left, bottom_right = st.columns(2)
        with bottom_left:
            try:
                card = st.container(border=True)
            except TypeError:
                card = st.container()
            with card:
                st.markdown("**합·충·형·파·해**")
                st.markdown(interaction_overview)

        with bottom_right:
            try:
                card = st.container(border=True)
            except TypeError:
                card = st.container()
            with card:
                st.markdown("**한 줄 처방**")
                st.markdown(prescription)

    if "중첩" in interaction_overview:
        st.caption("이 사람아, 같은 지지쌍에서 합·형·파가 한꺼번에 잡힐 때는 복합 신호로 묶어 보여준단다.")
    st.caption("천간·지지 낱낱이, 원국 반응, 합충 상세는 아래 상세 보기에서 확인해봐.")

    with st.expander("🌤 오늘의 처방 상세 보기", expanded=False):
        render_today_compass_card(payload)


def render_saju_forecast_box(forecast: dict) -> None:
    """오늘의 예보 카드 — 대운·세운·월운·일운 종합 압박 지도."""
    if not forecast:
        return

    level      = str(forecast.get("level", "보통"))
    lc         = str(forecast.get("level_color", "#94a3b8"))
    lbg        = str(forecast.get("level_bg", "#111111"))
    risk       = float(forecast.get("risk", 0))
    oppo       = float(forecast.get("opportunity", 0))
    summary    = str(forecast.get("summary", ""))
    signals    = list(forecast.get("signals", []))
    dw         = str(forecast.get("daewoon", "-") or "-")
    sw         = str(forecast.get("sewoon",  "-") or "-")
    ww         = str(forecast.get("wolwoon", "-") or "-")
    iw         = str(forecast.get("ilwoon",  "-") or "-")

    SIGN_ICON  = {"pressure": "⚠️", "mixed": "🔀", "positive": "✅"}
    SIGN_COLOR = {"pressure": "#ef4444", "mixed": "#f59e0b", "positive": "#22c55e"}

    # ── 요약 헤더 카드 ────────────────────────────────────
    st.markdown(
        f"<div style='background:{lbg};border:1px solid {lc};"
        f"border-radius:10px;padding:14px 18px;margin-bottom:10px;'>"
        f"<div style='display:flex;justify-content:space-between;align-items:center;"
        f"margin-bottom:8px;'>"
        f"<span style='font-size:11px;font-weight:700;color:#b89a6b;letter-spacing:2px;'>"
        f"오늘의 예보 · 대운·세운·월운·일운 종합</span>"
        f"<span style='background:{lc};color:#fff;font-size:12px;font-weight:700;"
        f"padding:3px 10px;border-radius:20px;'>{level}</span>"
        f"</div>"
        f"<div style='font-size:14px;color:#e2e8f0;line-height:1.7;margin-bottom:10px;'>"
        f"{summary}"
        f"</div>"
        f"<div style='display:flex;gap:16px;flex-wrap:wrap;'>"
        f"<span style='font-size:12px;color:#94a3b8;'>"
        f"압박 지수 <b style='color:{lc};'>{risk:.0f}</b></span>"
        f"<span style='font-size:12px;color:#94a3b8;'>"
        f"기회 지수 <b style='color:#22c55e;'>{oppo:.0f}</b></span>"
        f"<span style='font-size:11px;color:#64748b;margin-left:auto;'>"
        f"대운 {dw} · 세운 {sw} · 월운 {ww} · 일운 {iw}</span>"
        f"</div>"
        f"</div>",
        unsafe_allow_html=True,
    )

    # ── 신호 카드 (expander) ──────────────────────────────
    if signals:
        with st.expander("📡 주요 신호 자세히 보기", expanded=False):
            st.caption(
                "오늘의 예보는 대운·세운·월운·일운이 원국을 어떻게 건드리는지 살펴보는 참고용 흐름입니다. "
                "일운 하나만으로 좋고 나쁨을 단정하지 않고, 원국과 큰 운에서 반복되는 신호가 "
                "오늘 촉발되는지를 중심으로 봅니다."
            )
            for sig in signals:
                sign  = str(sig.get("sign", "pressure"))
                icon  = SIGN_ICON.get(sign, "⚠️")
                sc    = SIGN_COLOR.get(sign, "#ef4444")
                st.markdown(
                    f"<div style='background:#111111;border-left:3px solid {sc};"
                    f"border-radius:0 6px 6px 0;padding:10px 14px;margin-bottom:8px;'>"
                    f"<div style='display:flex;justify-content:space-between;"
                    f"align-items:center;margin-bottom:4px;'>"
                    f"<span style='font-size:13px;font-weight:700;color:{sc};'>"
                    f"{icon} {sig.get('name','')} · {sig.get('branches','')}</span>"
                    f"<span style='font-size:11px;color:#94a3b8;'>"
                    f"점수 {sig.get('score',0):.0f}</span>"
                    f"</div>"
                    f"<div style='font-size:13px;color:#cbd5e1;line-height:1.6;'>"
                    f"{sig.get('desc','')}</div>"
                    f"<div style='font-size:12px;color:#64748b;margin-top:4px;'>"
                    f"→ {sig.get('tip','')}</div>"
                    f"</div>",
                    unsafe_allow_html=True,
                )
    else:
        st.caption("감지된 주요 신호가 없습니다. 평소 루틴대로 움직이기 좋은 날입니다.")

    st.caption("※ 이 예보는 명리학적 참고용 신호입니다. 의료·법률·투자·계약 판단을 대신하지 않습니다.")


def share_card_strength_keywords(char: Dict[str, str], result: Dict[str, object]) -> List[str]:
    role = str(char.get("role", "") or "")
    role_keywords = {
        "독립가": ["자기 기준 선명", "밀어붙이는 힘", "버티는 체력"],
        "아이디어 뱅크": ["발상 정리력", "구조화 감각", "실행 설계력"],
        "전략가": ["판 읽는 현실감", "정리·설계 능력", "결과 계산 감각"],
        "리더": ["책임을 붙잡는 힘", "기준 세우는 능력", "역할 장악력"],
        "책사": ["깊게 읽는 분석력", "빈틈 보는 관찰력", "구조화 능력"],
        "밸런서": ["관계 조율력", "흐름 균형감", "환경 적응력"],
    }
    keywords = list(role_keywords.get(role, []))
    dominant, _weak = _dominant_and_weak_elements(result)
    element_keywords = {
        "목": "성장 추진력",
        "화": "표현 추진력",
        "토": "버티는 안정감",
        "금": "기준 판단력",
        "수": "흐름 파악력",
    }
    el_key = element_keywords.get(dominant[0])
    if el_key and el_key not in keywords:
        keywords.append(el_key)
    return keywords[:4] if keywords else ["균형감", "관찰력", "회복력"]


def share_card_overload_signal(char: Dict[str, str], result: Dict[str, object]) -> str:
    operation = str(char.get("operation", "") or "")
    role = str(char.get("role", "") or "")

    if "준비가 힘" in operation:
        return "준비가 부족하면 쉽게 지치고, 기준이 높아질 수 있음"
    if "스스로" in operation or "자기 주도" in operation:
        return "혼자 끌고 가려다 속도와 부담이 같이 올라갈 수 있음"
    if "상황을 읽" in operation or "흐름에 맞" in operation:
        return "너무 맞추다 보면 자기 리듬이 흐려질 수 있음"
    if "균형" in operation:
        return "모두를 맞추려다 결정이 늦어질 수 있음"
    if "연결" in operation:
        return "주변 환경이 흔들리면 에너지 회복이 늦어질 수 있음"

    role_overload = {
        "전략가": "계산이 많아지면 시작이 늦어질 수 있음",
        "책사": "생각이 깊어질수록 실행 타이밍을 놓칠 수 있음",
        "리더": "책임감이 과해지면 혼자 떠안기 쉬움",
        "아이디어 뱅크": "생각이 많아지면 정리 전 에너지가 흩어질 수 있음",
        "독립가": "기준이 강해지면 주변과 박자가 어긋날 수 있음",
    }
    return role_overload.get(role, "강점이 과해질 때는 잠깐 멈춰 리듬을 조정하는 편이 좋음")


def share_card_one_liner(char: Dict[str, str], result: Dict[str, object]) -> str:
    title = str(char.get("title", "") or "")
    operation = str(char.get("operation", "") or "")
    role = str(char.get("role", "") or "")

    if "화초" in title:
        return "천천히 뿌리내릴수록 오래 강해지는 타입"
    if "바위" in title or "보석" in title:
        return "기준이 잡힐수록 판단과 설계가 또렷해지는 타입"
    if "태양" in title or "불꽃" in title:
        return "불이 붙으면 주변까지 함께 움직이게 만드는 타입"
    if "바다" in title or "맑은 물" in title or "물길" in title:
        return "흐름을 읽고 필요한 방향으로 조용히 움직이는 타입"
    if "거목" in title:
        return "시간을 들여 큰 흐름을 세울수록 힘이 나는 타입"

    if "준비가 힘" in operation:
        return "준비가 갖춰질수록 힘이 깊고 오래 가는 타입"
    if role == "전략가":
        return "판을 읽고 필요한 순간에 정확히 들어가는 타입"
    if role == "책사":
        return "조용히 보다가 핵심을 정확히 짚어내는 타입"
    return "자기 리듬을 잡을수록 강점이 선명해지는 타입"


def share_card_operation_interpretation(char: Dict[str, str], result: Dict[str, object]) -> str:
    """공유카드의 메타 설명 대신 실제 작동 해석을 만든다."""
    op = energy_operation_profile(result)
    axis = operation_axis_profile(op, result)
    label = str(axis.get("label", "균형 조율권"))
    note = str(axis.get("note", ""))
    operation = str(char.get("operation", "") or "")
    if "준비가 힘" in operation:
        return f"{label}. 준비와 정보가 채워질수록 판단이 정교해지고, 한 번 잡은 판은 끝까지 정리하는 힘이 살아납니다."
    if "스스로" in operation or "자기 주도" in operation:
        return f"{label}. 내 방향을 먼저 정한 뒤 밀어붙일 때 존재감이 강하게 살아납니다."
    if "상황을 읽" in operation or "흐름에 맞" in operation:
        return f"{label}. 상황의 흐름을 읽고 타이밍을 맞출수록 장점이 살아납니다."
    if "균형" in operation:
        return f"{label}. 사람과 상황 사이에서 우선순위를 잡을 때 안정적인 결과를 만듭니다."
    return f"{label}. {note or '자기 리듬을 잡을수록 강점이 선명해집니다.'}"



