def _luck_station_icon(ganzhi: str, chart: Chart) -> str:
    if not ganzhi or len(str(ganzhi)) < 2:
        return ""
    branch = str(ganzhi)[1]
    for b in chart.branches:
        for a, c, _name in CLASHES:
            if (branch == a and b == c) or (branch == c and b == a):
                return ""
    for b in chart.branches:
        for a, c, _el, _name in SIX_HARMONIES:
            if (branch == a and b == c) or (branch == c and b == a):
                return ""
    return ""


def _luck_station_plain_detail(ganzhi: str, chart: Chart, useful: Dict[str, object], base_total: float, origin_result: Dict[str, object] | None = None) -> Dict[str, object]:
    """대운 글자가 원국과 만드는 합/충을 사용자용 설명으로 변환한다."""
    gz = str(ganzhi or "")
    branch = gz[1] if len(gz) >= 2 else ""
    stem = gz[0] if len(gz) >= 1 else ""
    bindings, clashes = [], []
    for b in chart.branches:
        for a, c, el, name in SIX_HARMONIES:
            if (branch == a and b == c) or (branch == c and b == a):
                bindings.append(f"{name}: 원국의 {b}와 대운의 {branch}가 묶여 {el} 쪽 연결감이 생깁니다.")
        for a, c, name in CLASHES:
            if (branch == a and b == c) or (branch == c and b == a):
                clashes.append(f"{name}: 원국의 {b}와 대운의 {branch}가 부딪혀 변화·이동·자극이 커집니다.")
    mod, note = analyze_luck_interaction(gz, chart, useful, 15.0, origin_result)
    score = round(max(0, min(100, float(base_total or 0) + float(mod or 0))), 1)
    if clashes and bindings:
        mood = "변화와 결속이 같이 오는 10년 흐름"
    elif clashes:
        mood = "변화·자극이 커지는 10년 흐름"
    elif bindings:
        mood = "연결감이 커지는 10년 흐름"
    else:
        mood = "큰 충돌 없이 지나가는 10년 흐름"
    return {"score": score, "mod": mod, "note": note, "bindings": bindings, "clashes": clashes, "mood": mood, "stem": stem, "branch": branch}


def render_daewun_train(payload: Dict[str, object]) -> None:
    """현재 대운 ±3개를 카드 그리드로 표시한다."""
    chart = payload.get("chart")
    result = payload.get("result", {}) or {}
    luck_flow = payload.get("luck_flow") or {}
    daewuns = payload.get("daewuns") or luck_flow.get("daewuns") or []
    current = luck_flow.get("current_daewun") if isinstance(luck_flow, dict) else None

    if not daewuns:
        st.info(
            "이 사람아, 생년월일시 자동 산출로 들어와야 10년 단위 대운 흐름이 나와. "
            "직접 입력 방식으로 들어오면 생년월일이 없으니까 대운을 계산을 못 하거든 — 자동 산출로 다시 들어와봐."
        )
        return

    # 현재 대운 인덱스
    current_idx = 0
    if current:
        for i, item in enumerate(daewuns):
            if (item.get("start_age") == current.get("start_age")
                    and item.get("ganzhi") == current.get("ganzhi")):
                current_idx = i
                break

    # 현재 ±3 (최대 7개)
    start_i = max(0, current_idx - 3)
    end_i   = min(len(daewuns), current_idx + 4)
    visible  = daewuns[start_i:end_i]

    base_total = float(result.get("total", 0) or 0)
    useful     = result.get("useful", {}) or {}

    def _dw_story(score, mod, mood, gz, is_current):
        """카드 안 한 줄 풀이."""
        if is_current:
            prefix = "지금 이 흐름이야."
        else:
            prefix = "이 시절엔"
        if score >= 75:
            feeling = "바람이 등을 밀어주는 때야."
        elif score >= 60:
            feeling = "순한 기운이 흐르는 편이야."
        elif score >= 45:
            feeling = "무난하지만 욕심은 줄이는 게 좋아."
        else:
            feeling = "거스르는 바람이야. 버티는 게 현명해."
        mod_hint = ""
        if mod >= 2:    mod_hint = " 원국보다 올라가 있어."
        elif mod <= -2: mod_hint = " 원국보다 눌리는 편이야."
        return f"{prefix} {feeling}{mod_hint}"

    # 대운 카드 그리드 HTML
    parts = ["<div style='display:flex;flex-wrap:wrap;gap:10px;margin-bottom:16px;'>"]
    for item in visible:
        gz       = str(item.get("ganzhi", "-"))
        age      = str(item.get("start_age", "-"))
        is_cur   = bool(current
                        and item.get("start_age") == current.get("start_age")
                        and item.get("ganzhi")    == current.get("ganzhi"))
        try:
            detail  = _luck_station_plain_detail(gz, chart, useful, base_total, result)
            score   = int(detail.get("score", 50) or 50)
            mod     = float(detail.get("mod", 0.0) or 0.0)
            mood    = str(detail.get("mood", "보통 흐름"))
            note    = _clean_display_text(str(detail.get("note", "")))
            has_clash   = bool(detail.get("clashes"))
            has_binding = bool(detail.get("bindings"))
        except Exception:
            score, mod, mood, note, has_clash, has_binding = 50, 0.0, "보통", "", False, False

        story = _dw_story(score, mod, mood, gz, is_cur)

        if is_cur:
            border = "3px solid #2563eb"
            bg     = "#080e28"
            badge_bg = "#2563eb"
            badge_text = "현재"
        elif mod >= 2:
            border = "1.5px solid #16a34a"
            bg     = "#0d1e14"
            badge_bg = "#16a34a"
            badge_text = "순"
        elif mod <= -2:
            border = "1.5px solid #dc2626"
            bg     = "#0f0f0f"
            badge_bg = "#dc2626"
            badge_text = "역"
        else:
            border = "1.5px solid #4a3a44"
            bg     = "#111111"
            badge_bg = "#4a3a44"
            badge_text = "평"

        signal_icon = ""
        if has_clash:   signal_icon = " ⚡"
        elif has_binding: signal_icon = " 🔗"

        parts.append(
            f"<div style='flex:1;min-width:120px;max-width:180px;background:{bg};"
            f"border:{border};border-radius:10px;padding:12px 10px;'>"
            f"<div style='display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;'>"
            f"<span style='background:{badge_bg};color:#fff;border-radius:4px;padding:1px 7px;"
            f"font-size:13px;font-weight:700;'>{badge_text}</span>"
            f"<span style='font-size:13px;color:#a0b4bc;'>{html.escape(age)}세~</span></div>"
            f"<div style='font-size:20px;font-weight:800;color:#93c5fd;text-align:center;"
            f"letter-spacing:2px;margin-bottom:4px;'>{html.escape(gz)}{signal_icon}</div>"
            f"<div style='font-size:13px;color:#b0c4cc;margin-bottom:4px;text-align:center;'>"
            f"체감 {score}% · {mod:+.1f}</div>"
            f"<div style='font-size:12px;color:#b89a6b;line-height:1.5;'>{html.escape(story)}</div>"
            f"</div>"
        )
    parts.append("</div>")
    st.markdown("".join(parts), unsafe_allow_html=True)

    # 합·충 상세는 현재 대운만 표시
    if current:
        try:
            gz_cur = str(current.get("ganzhi", "-"))
            detail_cur = _luck_station_plain_detail(gz_cur, chart, useful, base_total, result)
            if detail_cur.get("bindings"):
                st.caption("🔗 현재 대운 — 원국과 합으로 묶이는 글자가 있어. 결합·변화의 신호야.")
                _markdown_signal_cards(detail_cur["bindings"])
            if detail_cur.get("clashes"):
                st.caption("⚡ 현재 대운 — 원국과 충으로 움직이는 글자가 있어. 변동·이동 신호야.")
                _markdown_signal_cards(detail_cur["clashes"])
        except Exception:
            pass


def chemistry_type_from_compatibility(compatibility: Dict[str, object]) -> Dict[str, str]:
    axes = compatibility.get("axes") or {}
    complement = float(axes.get("상호 보완성", 0) or 0)
    alliance = float(axes.get("동맹성", 0) or 0)
    sync = float(axes.get("흐름 동조성", 0) or 0)
    tension = float(axes.get("긴장도", 0) or 0)
    if complement >= max(alliance, sync, 45) and complement >= 68:
        return {"title": "퍼즐형 케미", "stamp": "", "desc": "서로 부족한 오행과 온도감을 채워주는 보완형 관계입니다."}
    if alliance >= max(complement, tension, 45) and alliance >= 68:
        return {"title": "거울형 케미", "stamp": "🪞", "desc": "닮은 결이나 합의 신호가 커서 말이 잘 통하는 동맹형 관계입니다."}
    if tension >= 60:
        return {"title": "스파크형 케미", "stamp": "", "desc": "충과 긴장 신호가 있어 자극, 변화, 성장 압력이 큰 관계입니다."}
    if sync >= 65:
        return {"title": "리듬형 케미", "stamp": "🌊", "desc": "기운이 흘러가는 방향이 비슷해 호흡을 맞추기 쉬운 관계입니다."}
    return {"title": "조율형 케미", "stamp": "🎛️", "desc": "한쪽으로 단정하기보다 거리, 역할, 기대치를 맞추며 안정되는 관계입니다."}


def relationship_orientation_from_compatibility(compatibility: Dict[str, object]) -> Dict[str, str]:
    """궁합축을 바탕으로 케미가 가장 빛나는 관계 지향점을 추천한다."""
    axes = compatibility.get("axes") or {}
    complement = float(axes.get("상호 보완성", 0) or 0)
    alliance = float(axes.get("동맹성", 0) or 0)
    sync = float(axes.get("흐름 동조성", 0) or 0)
    tension = float(axes.get("긴장도", 0) or 0)
    buffer_val = float(axes.get("긴장 완충력", max(0, 100 - tension)) or max(0, 100 - tension))
    clash = int(compatibility.get("clash_count", 0) or 0)
    harmony = int(compatibility.get("harmony_count", 0) or 0)

    # 우선순위는 "관계에서 체감되는 자리" 기준. 점수형 우열이 아니라 포지션 추천이다.
