def render_shinsal_badge_cards(payload: Dict[str, object] | Dict[str, object], prefix: str = "single") -> None:
    """공망·신살을 큰 카드로 보여준다. payload 또는 result dict를 모두 허용한다."""
    if isinstance(payload, dict) and "result" in payload and "chart" in payload:
        result = payload.get("result") or {}
        chart = payload.get("chart")
    else:
        result = payload if isinstance(payload, dict) else {}
        chart = None

    shinsal = result.get("shinsal") or {}
    hits = shinsal.get("hits") or []
    if not hits or chart is None:
        return

    seen = set()
    cards = []
    for hit in hits:
        name = str(hit.get("신살", hit.get("name", "")) or "")
        pos = str(hit.get("위치", "-") or "-")
        key = (name, pos)
        if key in seen:
            continue
        seen.add(key)
        profile = _shinsal_card_profile(name, hit, chart)
        cards.append(
            "<div class='shinsal-card'>"
            "<div class='shinsal-head'>"
            f"<div class='shinsal-icon'>{html.escape(str(profile['icon']))}</div>"
            "<div>"
            f"<div class='shinsal-name'>{html.escape(str(profile['title']))}</div>"
            f"<div class='shinsal-type'>{html.escape(str(profile['tag']))}</div>"
            "</div>"
            "</div>"
            f"<span class='shinsal-badge'>{html.escape(str(profile['badge']))}</span>"
            f"<div class='shinsal-summary'>{html.escape(str(profile['summary']))}</div>"
            "<div class='shinsal-detail'>"
            "<div class='shinsal-detail-title'>성립 근거</div>"
            f"<div class='shinsal-detail-body'>{html.escape(str(profile['how']))}<br><b>실제 확인 위치:</b> {html.escape(str(profile['position']))}</div>"
            "</div>"
            "<div class='shinsal-detail'>"
            "<div class='shinsal-detail-title'>의미</div>"
            f"<div class='shinsal-detail-body'>{html.escape(str(profile['meaning']))}</div>"
            "</div>"
            "<div class='shinsal-detail'>"
            "<div class='shinsal-detail-title'>읽는 법</div>"
            f"<div class='shinsal-detail-body'>{html.escape(str(profile['reading']))}</div>"
            "</div>"
            f"<div class='shinsal-pos'>성격: {html.escape(str(profile['nature']))} · 점수 반영: {html.escape(str(profile['score']))}</div>"
            "</div>"
        )

    st.markdown("#### 🎴 특수 배지 카드")
    st.caption("공망·신살은 원국의 중심 판단을 대체하지 않지만, 사건감과 체감 포인트를 보강하는 특수 신호입니다. 어떤 자리에 잡혔는지 함께 확인해 보세요.")
    st.markdown("<div class='shinsal-grid'>" + "".join(cards[:8]) + "</div>", unsafe_allow_html=True)
    st.markdown("<div class='shinsal-footnote'>※ 공망·신살은 단독으로 길흉을 확정하지 않습니다. 다만 v5.81부터는 위치와 중복 여부에 따라 체감 보정으로 일부 반영합니다.</div>", unsafe_allow_html=True)


def interaction_compound_role_notes(result: Dict[str, object]) -> List[str]:
    """합국에 참여한 글자가 신살 등 다른 보조 의미도 가질 때 짧게 알려준다."""
    interactions = result.get("interactions") or []
    shinsal = result.get("shinsal") or {}
    hits = shinsal.get("hits") or []
    notes: List[str] = []
    branches = set(BRANCHES.keys())

    for it in interactions:
        if it.get("type") not in ["삼합", "방합", "반합", "육합"]:
            continue
        name = str(it.get("name", ""))
        involved = [b for b in branches if b in name]
        if not involved:
            continue
        for hit in hits:
            hit_name = str(hit.get("신살", hit.get("name", "보조 신호")))
            raw_pos = str(hit.get("위치", ""))
            for b in involved:
                if b and b in raw_pos:
                    msg = f"{b}는 {hit_name} 신호이면서 {name}에도 참여합니다. 합국은 결속을 보태지만, 해당 글자의 원래 의미도 함께 봅니다."
                    if msg not in notes:
                        notes.append(msg)
    return notes[:3]


def split_character_label(text: str) -> Tuple[str, str]:
    if "—" in text:
        left, right = text.split("—", 1)
        return left.strip(), right.strip()
    if "-" in text:
        left, right = text.split("-", 1)
        return left.strip(), right.strip()
    return text.strip(), ""


def render_ability_bar_summary(result: Dict[str, object], prefix: str = "single") -> None:
    rows = category_totals(result["categorized_scores"])
    st.markdown("#### 3대 능력치")
    for row in rows:
        info = axis_info_from_category(row["카테고리"])
        score = float(row.get("반영치", row.get("점수", 0)))
        max_score = float(row.get("기준", row.get("배점", 0)) or 0)
        pct = 0 if max_score <= 0 else max(0, min(100, score / max_score * 100))
        st.markdown(f"""
        <div class="ability-bar-row">
            <div class="ability-bar-head">
                <span class="ability-bar-title">{info['icon']} {info['primary']} <span style="font-size:.88rem;color:#d4b896;">({info['legacy']})</span></span>
                <span class="ability-bar-score">{score:.1f} / {max_score:.0f}</span>
            </div>
            <div style="font-size:.82rem;color:#d4b896;font-weight:760;margin-bottom:.32rem;">{info['short']} · {info['meaning']}</div>
            <div class="ability-bar-track">
                <div class="ability-bar-fill" style="width:{pct:.1f}%;"></div>
            </div>
        </div>
        """, unsafe_allow_html=True)
    render_strong_axis_note(result)


def render_score_formula_diagram(result: Dict[str, object], prefix: str = "single") -> None:
    # v5.150: synced 값 사용 → 3대 능력치 합 = 총점
    totals = category_totals_synced_to_total(result) if result.get("categorized_scores") and result.get("total") is not None else category_totals(result.get("categorized_scores", {}))
    values = {axis_info_from_category(row["카테고리"])["primary"]: float(row.get("반영치", row.get("점수", 0))) for row in totals}
    size_score = values.get("기초체력", 0.0)
    flow_score = values.get("흐름과 연결", 0.0)
    _flow_max_v = float(next((r.get("max", 0) for r in (result.get("score_map") or {}).values() if False), 0) or 0)
    _flow_pct_v = 0.0
    try:
        _sm = result.get("score_map") or {}
        for _k, _v in _sm.items():
            if "순환" in str(_k) or "흐름" in str(_k):
                _flow_pct_v = float(_v.get("pct", 0) or 0)
                break
        if _flow_pct_v == 0:
            _fsm2 = {}
            for row in (result.get("categorized_scores") or []):
                from_ai = axis_info_from_category(row["카테고리"])
                if from_ai.get("primary") == "흐름과 연결":
                    _flow_pct_v = float(row.get("pct", 0) or 0)
                    break
    except Exception:
        _flow_pct_v = 0.0
    _flow_grade = ("극강" if _flow_pct_v > 80 else "최강" if _flow_pct_v > 75 else "강함+" if _flow_pct_v > 70 else "강함" if _flow_pct_v > 65 else "보통+" if _flow_pct_v > 60 else "보통" if _flow_pct_v > 55 else "약함+" if _flow_pct_v > 50 else "약함")
    expr_score = values.get("현실작동력", 0.0)
    base_total = size_score + flow_score + expr_score
    total = float(result.get("total", 0.0))
    holistic = float(result.get("holistic", {}).get("adjustment", 0.0))
    shinsal = float(result.get("shinsal", {}).get("adjustment", 0.0))
    st.markdown(f"""
    <div style="background:#141414;border:1px solid rgba(212,168,83,0.45);border-radius:18px;padding:1rem 1rem 1.1rem 1rem;margin:0.35rem 0 1rem 0;">
        <div style="font-weight:900;color:#d4b896;font-size:1.04rem;margin-bottom:0.7rem;">총점 계산 한눈에 보기</div>
        <div style="display:flex;flex-wrap:wrap;align-items:center;gap:0.55rem;">
            <div style="flex:1 1 170px;background:#141414;border:1px solid #f2ced8;border-radius:14px;padding:0.8rem;text-align:center;"><div style="font-size:1.02rem;color:#d4b896;font-weight:950;">기초체력</div><div style="font-size:.88rem;color:#d4b896;font-weight:800;">(기운의 크기)</div><div style="font-size:1.35rem;color:#d95b84;font-weight:900;">{size_score:.1f}</div><div style="font-size:.88rem;color:#d4b896;">오행·월령·통근·일간</div></div>
            <div style="font-size:1.2rem;font-weight:900;color:#b98195;">+</div>
            <div style="flex:1 1 170px;background:#141414;border:1px solid #f2ced8;border-radius:14px;padding:0.8rem;text-align:center;"><div style="font-size:1.02rem;color:#d4b896;font-weight:950;">흐름과 연결</div><div style="font-size:.88rem;color:#d4b896;font-weight:800;"></div><div style="font-size:1.35rem;color:#f59e0b;font-weight:900;">{_flow_grade}</div><div style="font-size:.88rem;color:#d4b896;">조후·십성 흐름</div></div>
            <div style="font-size:1.2rem;font-weight:900;color:#b98195;">+</div>
            <div style="flex:1 1 170px;background:#141414;border:1px solid #f2ced8;border-radius:14px;padding:0.8rem;text-align:center;"><div style="font-size:1.02rem;color:#d4b896;font-weight:950;">현실작동력</div><div style="font-size:.88rem;color:#d4b896;font-weight:800;">(기운의 발현)</div><div style="font-size:1.35rem;color:#d95b84;font-weight:900;">{expr_score:.1f}</div><div style="font-size:.88rem;color:#d4b896;">합충·현실 작동</div></div>
            <div style="font-size:1.2rem;font-weight:900;color:#b98195;">+</div>
            <div style="flex:1 1 150px;background:#141414;border:1px solid #f2ced8;border-radius:14px;padding:0.8rem;text-align:center;"><div style="font-size:0.94rem;color:#d4b896;font-weight:950;">신살·공망</div><div style="font-size:1.18rem;color:#d95b84;font-weight:900;">{shinsal:+.1f}</div><div style="font-size:.88rem;color:#d4b896;">체감 보정</div></div>
            <div style="font-size:1.2rem;font-weight:900;color:#b98195;">=</div>
            <div style="flex:1 1 180px;background:linear-gradient(135deg,#fefce8,#fffafc);border:2px solid #ebb2c4;border-radius:16px;padding:0.85rem;text-align:center;"><div style="font-size:0.92rem;color:#d4b896;font-weight:800;">대표 총점</div><div style="font-size:1.6rem;color:#92400e;font-weight:950;">{total:.1f}점</div></div>
        </div>
    </div>
    """, unsafe_allow_html=True)
    if abs(total - base_total) >= 0.1:
        st.caption(f"참고: 신살·공망 체감 보정 {shinsal:+.1f}점을 대표 점수에 반영했습니다. 전체 인상 보정 {holistic:+.1f}점은 해설용 참고 신호입니다.")
    else:
        st.caption("대표 점수는 기초체력 + 흐름과 연결 + 현실작동력에 신살·공망 체감 보정을 더한 값입니다.")




def _luck_card_class_from_mod(mod: float) -> str:
    try:
        mod = float(mod)
    except Exception:
        mod = 0.0
    if mod >= 2.0:
        return "good"
    if mod <= -2.0:
        return "hard"
    if mod < 0:
        return "caution"
    return ""


def _luck_element_badges(gz: str) -> str:
    if not gz or len(gz) < 2:
        return ""
    stem, branch = gz[0], gz[1]
    badges = []
    if stem in STEMS:
        el = STEMS[stem]["element"]
        badges.append(f"<span class='manse-luck-el el-{html.escape(el)}'>천간 {html.escape(el)}</span>")
    if branch in BRANCHES:
        el = BRANCHES[branch]["element"]
        badges.append(f"<span class='manse-luck-el el-{html.escape(el)}'>지지 {html.escape(el)}</span>")
    return "<div class='manse-luck-elrow'>" + "".join(badges) + "</div>"


def render_manse_daewun_cards(payload: Dict[str, object]) -> None:
    """만세력 원국 화면 안의 대운 배열을 카드형 UI로 표시한다."""
    chart = payload.get("chart")
    result = payload.get("result", {}) or {}
    luck_flow = payload.get("luck_flow") or {}
    daewuns = payload.get("daewuns") or []
    if not chart or not daewuns:
        st.info("대운 배열은 생년월일시 자동 산출 모드에서 표시됩니다.")
        return

    current = luck_flow.get("current_daewun") if isinstance(luck_flow, dict) else None
    base_total = float(result.get("total", 0) or 0)
    useful = result.get("useful", {}) or {}
    html_parts = [
        "<div class='manse-luck-wrap'>",
        "<div class='manse-luck-head'>",
        "<div><div class='manse-luck-title'>〽️ 대운 배열</div><div class='manse-luck-sub'>10년 단위로 들어오는 큰 배경값입니다. 현재 대운은 진한 테두리로 표시합니다.</div></div>",
        f"<div class='manse-luck-chip'>{len(daewuns)}개 흐름</div>",
        "</div><div class='manse-luck-grid'>",
    ]
    for idx, item in enumerate(daewuns):
        gz = str(item.get("ganzhi", "-"))
        age = str(item.get("start_age", "-"))
        is_current = bool(current and item.get("start_age") == current.get("start_age") and item.get("ganzhi") == current.get("ganzhi"))
        try:
            detail = _luck_station_plain_detail(gz, chart, useful, base_total, result)
            mod = float(detail.get("mod", 0.0) or 0.0)
            score = detail.get("score", "-")
            mood = str(detail.get("mood", "10년 흐름"))
            note = _clean_display_text(str(detail.get("note", "무난함")))
        except Exception:
            mod, score, mood, note = 0.0, "-", "10년 흐름", "대운 원국 반응을 간단히 참고합니다."
        card_cls = "manse-luck-card " + _luck_card_class_from_mod(mod) + (" current" if is_current else "")
        badge = "현재 대운" if is_current else f"{idx+1}번째 대운"
        mini = "" if mod <= -2.0 else ("＋" if mod >= 2.0 else "〽")
        html_parts.append(
            f"<div class='{card_cls}'>"
            f"<div class='manse-luck-badge'>{html.escape(badge)}</div>"
            f"<div class='manse-luck-age'>{html.escape(age)}세부터 10년</div>"
            f"<div class='manse-luck-gz'>{html.escape(gz)}</div>"
            f"{_luck_element_badges(gz)}"
            f"<div class='manse-luck-score'>체감 {html.escape(str(score))}% · {mod:+.1f}</div>"
            f"<div class='manse-luck-note'>{html.escape(mood)}<br>{html.escape(note)}</div>"
            f"<div class='manse-luck-mini'>{html.escape(mini)}</div>"
            "</div>"
        )
    html_parts.append("</div></div>")
    st.markdown("".join(html_parts), unsafe_allow_html=True)


def render_manse_sewun_cards(luck_flow: Dict[str, object]) -> None:
    """만세력 원국 화면 안의 5년 세운 참고를 카드형 UI로 표시한다."""
    rows = (luck_flow or {}).get("sewun_rows") or []
    if not rows:
        return
    html_parts = [
        "<div class='manse-luck-wrap'>",
        "<div class='manse-luck-head'>",
        "<div><div class='manse-luck-title'>📆 5년 세운 참고</div><div class='manse-luck-sub'>현재 대운 위에 해마다 얹히는 짧은 흐름입니다. 점수보다 변동 방향과 비고를 참고합니다.</div></div>",
        f"<div class='manse-luck-chip'>{len(rows)}년 보기</div>",
        "</div><div class='manse-sewun-grid'>",
    ]
    for r in rows:
        year = str(r.get("연도", "-"))
        gz = str(r.get("세운", "-"))
        score = str(r.get("점수", "-"))
        delta = str(r.get("변동", ""))
        note = _clean_display_text(str(r.get("비고", "")))
        html_parts.append(
            "<div class='manse-sewun-card'>"
            "<div class='manse-sewun-top'>"
            f"<div class='manse-sewun-year'>{html.escape(year)}</div>"
            f"<div class='manse-sewun-delta'>{html.escape(delta)}</div>"
            "</div>"
            f"<div class='manse-sewun-gz'>{html.escape(gz)}</div>"
            f"{_luck_element_badges(gz)}"
            f"<div class='manse-sewun-score'>참고점 {html.escape(score)}</div>"
            f"<div class='manse-sewun-note'>{html.escape(note)}</div>"
            "</div>"
        )
    html_parts.append("</div></div>")
    st.markdown("".join(html_parts), unsafe_allow_html=True)


def render_origin_identity_table(
    chart: Chart,
    luck_flow: "Dict | None" = None,
    daewuns: "list | None" = None,
    result: "Dict | None" = None,
) -> None:
    """만세력 원국 — 참조 이미지 스타일의 compact 테이블 + 오행 분포 + 대운/세운 한 화면 표시."""

    # ── 헬퍼 ─────────────────────────────────────────────────
    def _role(label: str, p: Pillar, is_stem: bool) -> str:
        if is_stem:
            return "일간" if label == "일주" else relation_to_day(chart.day_master, p.stem)
        return relation_to_day(chart.day_master, p.branch)

    def _jjg_compact(p: Pillar) -> str:
        """지장간을 세로로 한 글자씩 div로 반환 (모바일 칸 넘침 방지)."""
        if not p:
            return "?"
        return "".join(f"<div>{html.escape(hs)}</div>" for hs, _ in BRANCHES[p.branch]["hidden"])

    def _sinsal_tags(branch: str) -> str:
        """지지에 해당하는 신살 태그 문자열 반환 (e.g. '천을·역마')."""
        if not branch or branch in ("-", "?"):
            return ""
        tags = []
        _grp = _day_branch_group(chart.day.branch)
        if branch in CHEONEUL_BRANCHES.get(chart.day_master, []):
            tags.append("천을")
        if branch == MUNCHANG_BRANCH.get(chart.day_master, ""):
            tags.append("문창")
        if branch == YEOKMA_BRANCH.get(_grp, ""):
            tags.append("역마")
        if branch == DOHWA_BRANCH.get(_grp, ""):
            tags.append("도화")
        if branch == HWAGAE_BRANCH.get(_grp, ""):
            tags.append("화개")
        if branch in gongmang:
            tags.append("공망")
        return "·".join(tags)

    EL_COLOR = {"목": "목", "화": "화", "토": "토", "금": "금", "수": "수"}

    def _box(char: str, el: str, is_gold: bool = False) -> str:
        ec = EL_COLOR.get(el, "토")
        gold_cls = " el-금" if ec == "금" else ""
        return (
            f"<div class='mc-box manse-el-{ec}{gold_cls}'>"
            f"{html.escape(char)}</div>"
        )

    # ── 오행 분포 카운트 ──────────────────────────────────────
    def _count_ohaeng() -> Dict[str, int]:
        cnt: Dict[str, int] = {"목": 0, "화": 0, "토": 0, "금": 0, "수": 0}
        ps = [chart.year, chart.month, chart.day]
        if chart.hour:
            ps.append(chart.hour)
        for p in ps:
            se = STEMS.get(p.stem, {}).get("element", "")
            be = BRANCHES.get(p.branch, {}).get("element", "")
            if se in cnt: cnt[se] += 1
            if be in cnt: cnt[be] += 1
        return cnt

    OHAENG_LABEL = {"목": "木", "화": "火", "토": "土", "금": "金", "수": "水"}

    # ── 기둥 순서: 시주 | 일주 | 월주 | 년주 ─────────────────
    pillars = [
        ("시주", chart.hour),
        ("일주", chart.day),
        ("월주", chart.month),
        ("년주", chart.year),
    ]

    gongmang      = _gongmang_branches_for_day(chart.day.stem, chart.day.branch)
    gongmang_text = "·".join(f"{b}({_branch_ko(b)})" for b in gongmang) if gongmang else "없음"
    ganji         = ganji_text(chart)
    ohaeng_cnt    = _count_ohaeng()

    # ── 4운 간지 추출 ─────────────────────────────────────────
    from datetime import date as _d4
    _lf      = luck_flow or {}
    _dw_gz4  = str((_lf.get("current_daewun") or {}).get("ganzhi", "") or "")
    _sw_gz4  = ""
    _yr_lbl4 = str(_d4.today().year) + "년"
    for _r4 in (_lf.get("sewun_rows") or []):
        if str(_r4.get("연도", "")) == _yr_lbl4:
            _sw_gz4 = str(_r4.get("세운", "") or "")
            break
    _compass4 = {}
    if chart and result:
        try:
            _compass4 = today_compass_payload(chart, result)
        except Exception:
            pass
    _ww_gz4 = str(_compass4.get("month_gz", "") or "")
    _iw_gz4 = str(_compass4.get("day_gz",   "") or "")

    _4un = [
        ("대운", _dw_gz4, "#93c5fd"),
        ("세운", _sw_gz4, "#c4b5fd"),
        ("월운", _ww_gz4, "#86efac"),
        ("일운", _iw_gz4, "#fde68a"),
    ]

    # ── HTML 조립 ─────────────────────────────────────────────
    p = []  # parts

    # 타이틀
    p.append("<div class='manse-wrap'>")
    p.append(
        "<div class='manse-title'>"
        "<b>만세력 원국</b>"
        f"<span>{html.escape(ganji)}</span>"
        "</div>"
    )

    # ── 8열 통합 그리드 (일운→월운→세운→대운 | 시→일→월→년) ──────────
    _4un_disp = [
        ("일운", _iw_gz4, "#fde68a"),
        ("월운", _ww_gz4, "#86efac"),
        ("세운", _sw_gz4, "#c4b5fd"),
        ("대운", _dw_gz4, "#93c5fd"),
    ]
    _short_lbl = {"시주": "시", "일주": "일", "월주": "월", "년주": "년"}

    def _el_color(ch: str, is_stem: bool) -> str:
        tbl = {"목": "#34d399", "화": "#f87171", "토": "#fbbf24", "금": "#e5e7eb", "수": "#60a5fa"}
        d = STEMS if is_stem else BRANCHES
        el = d.get(ch, {}).get("element", "토")
        return tbl.get(el, "#fde68a")

    def _el_bg(ch: str, is_stem: bool) -> str:
        tbl = {"목": "rgba(134,239,172,.55)", "화": "rgba(252,165,165,.52)",
               "토": "rgba(253,224,71,.45)",  "금": "rgba(226,232,240,.50)",
               "수": "rgba(147,197,253,.52)"}
        d = STEMS if is_stem else BRANCHES
        el = d.get(ch, {}).get("element", "토")
        return tbl.get(el, "rgba(253,230,138,.35)")

    _S_4BG = "background:rgba(18,14,32,.55);"   # 4운 컬럼 행 배경 (cool tint)
    _S_WBG = "background:rgba(26,17,4,.55);"    # 원국 컬럼 행 배경 (warm tint)

    # ── inline-style 상수 (CSS class 대신 직접 적용) ─────────────
    _S_WRAP = ("display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:1px;"
               "margin-bottom:.6rem;background:#0d0d0d;border-radius:12px;"
               "padding:5px 2px 7px;border:1px solid rgba(212,168,83,.2);overflow:hidden;"
               "-webkit-text-size-adjust:none;text-size-adjust:none;")
    _S_LBL  = "font-size:7px;font-weight:700;text-align:center;padding:2px 0 2px;letter-spacing:.01em;overflow:hidden;"
    _S_SIP  = "font-size:7.5px;color:#b89a6b;font-weight:900;text-align:center;min-height:9px;line-height:1.1;padding:1px 0;overflow:hidden;"
    _S_GZ   = "font-size:1.05rem;font-weight:950;text-align:center;line-height:1.05;padding:1px 0;"
    _S_JJG  = "display:flex;flex-direction:column;align-items:center;font-size:10px;color:#6b7280;font-weight:700;text-align:center;line-height:1.3;padding:1px 0;"
    _S_UN   = "font-size:6.5px;color:#93c5fd;font-weight:800;text-align:center;padding:1px 0 2px;"
    _S_SS   = "font-size:6px;color:#f9a8d4;font-weight:800;text-align:center;padding:1px 0 3px;line-height:1.3;overflow:hidden;"
    _S_SEP  = "border-left:1px solid rgba(212,168,83,.3);"

    p.append(f"<div style='{_S_WRAP}'>")

    # ─ 레이블 행 ─
    for lbl4, gz4, col4 in _4un_disp:
        p.append(f"<div style='{_S_LBL}{_S_4BG}color:{col4}'>{html.escape(lbl4)}</div>")
    for i, (lbl, pi) in enumerate(pillars):
        sep_st = _S_SEP if i == 0 else ""
        lc = "#fde68a" if lbl == "일주" else "#999"
        p.append(f"<div style='{_S_LBL}{sep_st}{_S_WBG}color:{lc}'>{_short_lbl.get(lbl, lbl)}</div>")

    # ─ 천간 십성 행 ─
    for lbl4, gz4, col4 in _4un_disp:
        s4 = gz4[0] if gz4 and len(gz4) >= 1 else "-"
        ssip = relation_to_day(chart.day_master, s4) if s4 not in ("-", "?", "") else ""
        p.append(f"<div style='{_S_SIP}{_S_4BG}'>{html.escape(ssip)}</div>")
    for i, (lbl, pi) in enumerate(pillars):
        sep_st = _S_SEP if i == 0 else ""
        role = _role(lbl, pi, True) if pi else "-"
        p.append(f"<div style='{_S_SIP}{sep_st}{_S_WBG}'>{html.escape(role)}</div>")

    # ─ 천간 글자 행 ─
    for lbl4, gz4, col4 in _4un_disp:
        s4 = gz4[0] if gz4 and len(gz4) >= 1 else "-"
        sc = _el_color(s4, True) if s4 not in ("-", "?", "") else col4
        ebg = _el_bg(s4, True) if s4 not in ("-", "?", "") else ""
        bg4 = f"background:{ebg};" if ebg else _S_4BG
        p.append(f"<div style='{_S_GZ}{bg4}color:{sc}'>{html.escape(s4)}</div>")
    for i, (lbl, pi) in enumerate(pillars):
        sep_st = _S_SEP if i == 0 else ""
        if pi:
            sc = _el_color(pi.stem, True)
            ebg = _el_bg(pi.stem, True)
            day_extra = "border:1px solid rgba(253,230,138,.5);" if lbl == "일주" else ""
            p.append(f"<div style='{_S_GZ}{sep_st}background:{ebg};{day_extra}color:{sc}'>{html.escape(pi.stem)}</div>")
        else:
            p.append(f"<div style='{_S_GZ}{sep_st}color:#555'>?</div>")

    # ─ 지지 십성 행 ─
    for lbl4, gz4, col4 in _4un_disp:
        b4 = gz4[1] if gz4 and len(gz4) >= 2 else "-"
        bsip = relation_to_day(chart.day_master, b4) if b4 not in ("-", "?", "") else ""
